// Batch 1: كتاب النكاح ص4-84
const NO_N = `لم يتعرض لها الإمام النووي في المتن (المسألة من تعليقات الشيخ وفتاواه في الهامش).`;
const NO_O = `لم تُذكر أقوال أخرى.`;

module.exports = {
  title: `ترجيحات الشيخ ياسر في شرح صحيح مسلم بشرح النووي`,
  subtitle: `كتاب النكاح — الدفعة الأولى (من أول الكتاب إلى نهاية باب الوفاء بالشروط في النكاح، ص4–84 من التفريغ)`,
  sections: [
  {
    title: `مقدمة كتاب النكاح: حقيقة النكاح وما يترتب عليها (ص4–7، 14–15)`,
    items: [
    { q: `حقيقة النكاح: هل هو حقيقة في العقد أم في الوطء؟`, p: `5`,
      n: `ذكر للشافعية ثلاثة أوجه: أصحها أنه حقيقة في العقد مجاز في الوطء (صححه القاضي أبو الطيب وقطع به المتولي)، وبه جاء القرآن والأحاديث.`,
      o: `الثاني: حقيقة في الوطء مجاز في العقد، وهو قول أبي حنيفة. الثالث: حقيقة فيهما بالاشتراك.`,
      s: `حقيقة في العقد؛ لأنه الأكثر استعمالًا في القرآن، ولاتفاق العلماء على أن قوله تعالى (ولا تنكحوا ما نكح آباؤكم) يشمل من عقد عليها الأب وإن لم يطأها، وقوله (إذا نكحتم المؤمنات ثم طلقتموهن من قبل أن تمسوهن) صريح في تسمية العقد نكاحًا. وذكر أن ثمرة الخلاف تظهر في موضعين أو أكثر (المسألتان التاليتان).` },
    { q: `نكاح الزانية وتزويج الزاني (الزاني لا ينكح إلا زانية)`, p: `5–6`,
      n: NO_N,
      o: `من جعل النكاح حقيقة في الوطء قال: معنى الآية أن الزاني لا يجامع إلا زانية أو مشركة، فلا تدل على تحريم العقد.`,
      s: `القول الأول أظهر: الآية في العقد، فيحرم العقد على الزانية حتى تتوب إلى الله، ويحرم تزويج من عُرف بالزنى من العفيفة. ووجهه: أن حمله على الوطء لا يفيد شيئًا (فوصف الزنى كافٍ في حصوله)، ولوجود مرجِّح خارجي وهو سبب النزول (صحابي أراد أن يتزوج امرأة كانت زانية فسأل النبي ﷺ فأجابه بالآية)، وسياق الآية في العقد. ففيها دليل لمذهب الإمام أحمد في تحريم نكاح الزانية؛ فلا يجوز لمن يعرف زنى امرأة أن يتزوجها، ولا لامرأة تعرف زنى رجل أن تتزوجه. وفي صحة العقد إن وقع وجهان: أنه باطل، أو أنه فعل محرمًا وصح العقد.` },
    { q: `هل يحرِّم الحرامُ الحلالَ؟ (من زنى بامرأة: هل تحرم على أبيه وابنه؟ وهل تحرم عليه أمها وبنتها؟)`, p: `6، 15`,
      n: NO_N,
      o: `لا تحرم عند الشافعية ومن وافقهم، وتحرم عند مالك وأحمد (كما نقل الشيخ). ومن السلف من شدد حتى قال: من نظر إلى فرج امرأة حرمت على ابنه وأحفاده.`,
      s: `الذي يظهر أن الحرام لا يحرِّم الحلال؛ لأن الله إنما حرّم ما نكح الآباء بمعنى العقد، والتشديد في مجرد النظر لا دليل عليه. وفي الزنى بامرأة: هل تحرم عليه بنتها وأمها؟ الأقرب قول الشافعي؛ لأن آيات المصاهرة (وأمهات نسائكم) (وربائبكم اللاتي في حجوركم من نسائكم) والزانية ليست من نسائه فلا تحرم بنتها ولا أمها. فأمر المصاهرة مبني على العقد، وهو تعظيم لعقد النكاح، والوطء المحرم ليس له هذه الحرمة. أما وطء الأم الحلال فيحرم البنات، والقاعدة (الحرام لا يحرم الحلال) مأخوذة من الآية في أمر النكاح لا في الزنى.` },
    { q: `البنت المتخلقة من ماء الزنى: هل تحل للزاني؟ وهل ينسب إليه ولد الزنى إذا استلحقه؟`, p: `6–7`,
      n: NO_N,
      o: `الشافعي: يجوز أن يتزوجها لأنها ليست بنته شرعًا. شيخ الإسلام ابن تيمية: حديث (الولد للفراش) عند المنازعة فقط، فإن لم تكن منازعة جاز للزاني أن يستلحقه.`,
      s: `الصحيح أنها بنته فلا يجوز أن يتزوجها؛ لحديث جريج (يا غلام من أبوك؟ قال: فلان الراعي)، فسماه أبًا باعتبار أنه تكوّن من مائه، وإن لم يكن أبًا يرث ويُنسب إليه، ولا يرثها اتفاقًا. ولا يُنسب ولد الزنى للزاني ولو استلحقه عند عامة العلماء؛ لأنه لابد لثبوت النسب من فراش، وقول ابن تيمية مخالف لصريح الحديث وللأئمة الأربعة وأهل الفتوى. أما الأم فتثبت أمومتها ويُنسب ابنها إليها ولو من الزنى اتفاقًا. والخلاف في حل البنت خلاف ضعيف جدًا؛ فالمصاهرة تعظيم لعقد النكاح، أما النسب الحقيقي فثابت من جهة الخلقة.` },
    { q: `هل يحرم ابن الزنى أو بنت الزنى على أبناء الزاني من زوجته (إخوته من الأب)؟ (فتوى)`, p: `15`,
      n: NO_N,
      o: `قول من يرى أنه لا يثبت نسبه فلا تثبت الحرمة.`,
      s: `إذا عُلم أنه ابنه باعتراف أو شهود فالصحيح قول الجمهور أنه تحرم عليه أخواته من أبيه، فهن أخواته حقيقة؛ لحديث جريج، ولحديث (الولد للفراش وللعاهر الحجر، واحتجبي منه يا سودة)، فالنبي ﷺ حكم أنه أخوها في الظاهر، وأمرها بالاحتجاب لأجل ما عُلم في الباطن من الشبه؛ فإذا روعي ذلك في النظر فمن باب أولى أن يراعى في الوطء.` },
    { q: `وطء الشبهة وأحكامه`, p: `7`,
      n: NO_N,
      o: NO_O,
      s: `عامة أحكامه عند عامة أهل العلم مثل الوطء الحلال لوجود الشبهة؛ كمن تزوج امرأة بعقد باطل بغير ولي، أو ردّ امرأة طلقها قبل الدخول بغير عقد جديد يظنها امرأته: يثبت به النسب، ويُدرأ به الحد، وتجب به العدة وسائر الأحكام؛ فله في الجملة أحكام العقد الصحيح.` },
    { q: `إذا اغتصب الأب فتاة: هل تحرم على ابنه؟ (فتوى)`, p: `14`,
      n: NO_N,
      o: `من يقول: إذا وطئ الأب امرأة حرمت على ابنه، يجعلها محرمة عليه ولو كان ذلك بإكراه.`,
      s: `المكرَهة ليست في حكم الزانية شرعًا، فالإكراه مسقط لحكم الزنى في حقها. (وعلى ترجيح الشيخ أن الحرام لا يحرم الحلال فلا تحرم على الابن).` },
    { q: `رجل عقد على فتاة، وقبل الدخول زنى بأمها: هل تحرم عليه البنت؟ (فتوى)`, p: `14`,
      n: NO_N,
      o: `كثير من العلماء (القائلين بأن الحرام يحرم الحلال) يقولون: تحرم عليه البنت لأنها بنت موطوءته، وتحرم الأم لأنها أم زوجته بالعقد، فكلتاهما محرمتان.`,
      s: `الصحيح إن شاء الله أنه لا تحرم عليه البنت؛ لأنها ليست ربيبة، فالربيبة (من نسائكم اللاتي دخلتم بهن) والمرأة التي زنى بها ليست من نسائه.` },
    ]
  },
  {
    title: `باب استحباب النكاح لمن تاقت نفسه إليه ووجد مؤنه، واشتغال من عجز عن المؤن بالصوم (ص7–21)`,
    items: [
    { q: `حدّ سن الشباب`, p: `9`,
      n: `الشاب عند الشافعية من بلغ ولم يجاوز ثلاثين سنة.`,
      o: `ومنهم من يقول: إلى الأربعين.`,
      s: `نقل في الهامش القول الآخر (إلى الأربعين)، ولم يرجح صراحة.` },
    { q: `المراد بالباءة في الحديث`, p: `10`,
      n: `قولان يرجعان إلى معنى واحد: أصحهما أن المراد الجماع، فتقديره: من استطاع الجماع لقدرته على مؤنه (مؤن النكاح) فليتزوج. والثاني: المراد مؤن النكاح.`,
      o: `القول الثاني المذكور.`,
      s: `الخلاف في الحقيقة في المبنى اللغوي فقط، وإلا فمعنى القولين واحد؛ فقولهم (من استطاع الجماع لقدرته على مؤنه وهي مؤن النكاح فليتزوج) يدل على أن الكلام استقر على أن المقصود مؤنة الجماع.` },
    { q: `حكم النكاح لمن خاف على نفسه العنت (الوقوع في الحرام) وهو قادر عليه`, p: `11–12`,
      n: `النكاح مندوب عند العلماء كافة، لا يلزم التزوج ولا التسري سواء خاف العنت أم لا. واحتج الجمهور بقوله تعالى (فانكحوا ما طاب لكم من النساء... أو ما ملكت أيمانكم) فخيّر بين النكاح والتسري، قال المازري: ولو كان النكاح واجبًا لما خيّر بينه وبين التسري بالاتفاق؛ لأنه لا يصح التخيير بين واجب وغيره.`,
      o: `داود ومن وافقه من أهل الظاهر، ورواية عن أحمد: يلزمه إذا خاف العنت أن يتزوج أو يتسرى، مرة واحدة في العمر، ولم يشترط بعضهم خوف العنت. وقال أهل الظاهر: إنما يلزمه التزويج فقط لا الوطء.`,
      s: `رغم تكثير العلماء القائلين بعدم الوجوب ولو خاف العنت، فالصحيح أن أقل الأحوال وجوب الزواج إذا خاف العنت؛ لأن الأمر للوجوب، ولأن من خاف الوقوع في الحرام لزمه الأخذ بالأسباب التي تمنعه منه، وما لا يتم الواجب إلا به فهو واجب؛ فإذا كان يقع في الحرام وقد قدر على النكاح فالصحيح الرواية الأخرى عن أحمد أنه يجب عليه. ورد على المازري: الاتفاق الذي نقله على عدم وجوب التسري ليس بظاهر، فأهل الظاهر ورواية عن أحمد أوجبوا التسري إذا لم يتزوج وهو يخاف العنت، ولا يُحتج بمحل النزاع على النزاع. فالراجح: من خاف على نفسه العنت وقدر على الزواج وجب عليه أحد الأمرين (الزواج أو التسري).` },
    { q: `الأفضل في حق من يجد المؤن ولا تتوق نفسه: النكاح أم تركه للتخلي للعبادة؟`, p: `12، 16`,
      n: `الناس أربعة أقسام: من تتوق نفسه ويجد المؤن فيستحب له، ومن لا تتوق ولا يجد فيكره له، ومن تتوق ولا يجد فيكره له ويؤمر بالصوم، ومن يجد ولا تتوق: فمذهب الشافعي وجمهور أصحابه أن ترك النكاح والتخلي للعبادة أفضل، ولا يقال النكاح مكروه.`,
      o: `مذهب أبي حنيفة وبعض أصحاب الشافعي وبعض أصحاب مالك: النكاح له أفضل.`,
      s: `لا شك أن النكاح له أفضل، بل هناك حالة يكون فيها واجبًا [وهو أن يكون قادرًا على النكاح وتتوق نفسه إليه] ولم يذكرها النووي لأنها ليست من مذهبهم أصلًا. وقول من يستحب ترك النكاح للعبادة لمن لا تتوق نفسه ضعيف؛ فقصد عدم الزواج قصد فاسد، وتوقان النفس إلى النكاح أمر فطري موجود في كل الرجال إلا لمرض أو عارض، ومن زعم أنه لا تتوق نفسه فهو زعم في وقت معين يخدعه به الشيطان ثم تعود نفسه فيعسر عليه الأمر.` },
    { q: `معنى (فمن رغب عن سنتي فليس مني)، وحكم التعبد بترك النكاح والمبالغة في العبادة`, p: `12، 15–17`,
      n: `معناه: من رغب عنها إعراضًا عنها غير معتقد لها على ما هي عليه، أما من ترك النكاح على الصفة التي يستحب له تركها، أو ترك النوم على الفراش لعجزه أو لاشتغاله بعبادة مأذون فيها، فلا يتناوله هذا الذم.`,
      o: NO_O,
      s: `الظاهر أن من تعبّد بترك النكاح فقد فعل محرمًا، فـ(فليس مني) أقل أحوالها التحريم؛ وإن استحل مخالفة السنة كفر، وإلا فليس المقصود التكفير والخروج من الملة بل التغليظ، ومعنى (ليس مني) أي ليس على طريقتي وهديي (كحديث من حمل علينا السلاح). فالتعبد بترك النكاح ورؤية التبتل أفضل حرام، والنبي ﷺ نهى عن التبتل نهيًا شديدًا فكيف يقال إنه الأفضل والمستحب؟! ومن ظن أن المبالغة في العبادة أكمل من هدي النبي ﷺ فليس على طريقته؛ وقول (لا أتزوج النساء) على عادة الرهبان وأهل الجاهلية، ومدرسة تهذيب النفس بتعذيبها وحرمانها من الشهوات المباحة مدرسة رهبانية ليست على طريقة أهل الإسلام. وما يتمدح به بعضهم من صلاة الفجر بوضوء العشاء أربعين سنة مذهب باطل مخالف لهدي النبي ﷺ ولو نقله بعض أهل العلم، وكذا صيام الدهر (لا صام من صام الأبد). والتعبد بترك الزواج حرام إلا أن يكون زواجًا محرمًا (كنكاح الزانية، أو من لا يقدر على مؤنه، أو من خاف ألا يعدل).` },
    { q: `التبتل، وهل يستحب لطالب العلم ترك النكاح؟ وهل الإعراض عن الشهوات المباحة مأمور به؟`, p: `18–19`,
      n: `التبتل: الانقطاع عن النساء وترك النكاح انقطاعًا إلى عبادة الله. ورد النبي ﷺ عليه التبتل محمول عند الشافعية على من تاقت نفسه ووجد مؤنه، وعلى من أضر به التبتل بالعبادات الكثيرة الشاقة. أما الإعراض عن الشهوات واللذات من غير إضرار بنفسه ولا تفويت حق لزوجة ولا غيرها ففضيلة لا منع منها، بل مأمور به.`,
      o: `كثير من الناس قالوا: يستحب لطالب العلم أن يترك النكاح مدة.`,
      s: `هذا التعريف ينطبق تمامًا على ما ذكروه من استحباب ترك النكاح للتفرغ للعبادة، وإن جعلوه في صورة معينة. والصحيح أنه ينبغي إذا وجد المؤن أن يتزوج: وجوبًا إن خاف العنت، واستحبابًا إن لم يخفه؛ والعنت هو الوقوع في الحرام، ولا يلزم أن يكون زنى الفرج، بل تكرار النظر ضرره عظيم على القلب، والصغائر مع الاجتماع تكون كبائر. ولو أذن الرسول ﷺ لعثمان في التبتل لاختصى الصحابة. أما قوله (بل مأمور به) فأين الأمر بذلك؟! لم يرد إلا الأوامر العامة بالنهي عن اتباع الشهوات، والمقصود نيلها في الحرام؛ فالأمر بالامتناع عن التكثر من الشهوات، لا بقطعها بالكلية وترك النكاح بالكلية، ويُتعجب كيف يقلد الفقهاء في ذلك مع وجود صريح السنة بخلافه.` },
    { q: `ترك أكل اللحم، أو ترك النوم على الفراش تعبدًا`, p: `17–18، 34`,
      n: `من ترك النوم على الفراش لعجزه عنه أو لاشتغاله بعبادة مأذون فيها فلا يتناوله الذم.`,
      o: NO_O,
      s: `العبادة تكون بالترك كما تكون بالفعل؛ فمن تعبد لله بترك ما فعله النبي ﷺ من الطيبات (كاللحم) كان مبتدعًا، أما من لا يرغب في اللحم لضرر أو نصيحة طبيب فجائز. وفي كلام النووي عن ترك النوم على الفراش نظر؛ فالأمر في هذا واسع يفعل ما تيسر، ولا يتكلف ترك النوم على الفراش بحجة الاشتغال بعبادة، فالنبي ﷺ قال (لكني أصلي وأنام). وفي فتوى: من كان الفراش اللين يمنعه من القيام للفجر لا يدخل في الحديث، فليترك ذلك الفراش ولا يتعبد بترك النوم على الفراش، وإن نام على الأرض أحيانًا فلا حرج، فالنبي ﷺ نام على حصير.` },
    { q: `إنكار المنكر على المنبر دون تسمية صاحبه (ما بال أقوام)`, p: `18`,
      n: `هو موافق للمعروف من خطبه ﷺ؛ إذا كره شيئًا خطب له وذكر كراهيته ولا يعين فاعله، وهذا من عظيم خلقه.`,
      o: NO_O,
      s: `هذا هو هدي النبي ﷺ في الوعظ والتذكير، وليس كما يفعل بعض الخطباء من ذكر الناس بأسمائهم على المنابر؛ فالعبرة أن يبلغ الأمر الشرعي للناس عمومًا دون تسمية أحد، وهي طريقة القرآن: لم يذكر من الكفار إلا أبا لهب، وذكر الآخرين بالصفة.` },
    { q: `الاختصاء، وكل ما يؤدي إلى قطع النسل (ربط القنوات، استئصال الرحم...)`, p: `20`,
      n: `الاختصاء في الآدمي حرام، صغيرًا كان أو كبيرًا.`,
      o: NO_O,
      s: `كل ما يؤدي إلى قطع النسل محرم، لأنه مُثلة وتضييع لمنفعة مقصودة. فربط مجاري المني لتعقيم الرجال لتحديد النسل محرم لا يجوز لمسلم الإقدام عليه، وكذا ربط قناة المبيض (الأنابيب) للنساء لا يجوز إلا إذا وُجد خطر على حياة الأم، لا لمجرد تقليل النسل أو كثرة الولادات أو الولادة القيصرية. وإزالة الرحم تجوز إن وُجد نزيف مستمر يُخشى معه على حياتها، وإزالة الخصية تجوز لورم يُخشى انتشاره، لا لمجرد التعب. والضعف بالحمل فطرة (حملته أمه وهنًا على وهن)، والذي يُنظر فيه: هل يصل الضعف إلى مرض يُخشى منه على صحتها؟ أما منع الحمل مدة مؤقتة بالوسائل المعروفة فهو في حكم العزل وسيأتي.` },
    { q: `خصاء الحيوان`, p: `20–21، 39`,
      n: `قال البغوي: يحرم خصاء كل حيوان لا يؤكل، وأما المأكول فيجوز خصاؤه في صغره ويحرم في كبره.`,
      o: NO_O,
      s: `أقرّه: غير المأكول لا مصلحة في خصائه. وأما المأكول ففي خصائه صغيرًا منفعة مقصودة وهي اكتناز اللحم، وقد ضحى النبي ﷺ بكبشين موجوءين (أي مرضوضي الخصيتين)، ولو كان محرمًا لنهى عنه ولم يضحِّ به، فإزالتها صغيرًا ليسمن ويكتنز اللحم أمر مشروع.` },
    { q: `عرض الزوجة الشابة على من ليست له زوجة شابة`, p: `13`,
      n: `فيه استحباب عرض الصاحب هذا على صاحبه الذي ليست له زوجة بهذه الصفة وهو صالح لزواجها.`,
      o: NO_O,
      s: `لا يمتنع أن يُعرض عليه زوجة شابة، وأما عند القوم (المعاصرين) فيُعد من المنكرات العظيمة؛ والصحابة كانوا يعرضون مثل هذا على بعضهم، وأكد ابن مسعود مشروعيته بأمر النبي ﷺ.` },
    { q: `الأفضل للشاب: تعجيل الزواج أم تأخيره لطلب العلم؟ (فتوى)`, p: `14`,
      n: NO_N,
      o: NO_O,
      s: `الأفضل ما أمر به النبي ﷺ، ولا يجوز أن يُسأل هذا السؤال بعد سماع الحديث، وتقديم كلام المشايخ على كلام النبي ﷺ من شؤم التقليد. فالشهوة من أعظم أسباب تشتت الذهن، والوقوع في الحرام من أعظم أسباب ظلمة القلب وضعف طلب العلم، فينبغي أن يكون الزواج دافعًا لطلب العلم؛ ومن يحبب للشباب ترك الزواج بحجة طلب العلم فقد خالف أحاديث النبي ﷺ. وعبد الرحمن بن يزيد تزوج وهو من أصغر الناس سنًا، وهكذا كان السلف.` },
    ]
  },
  {
    title: `باب ندب من رأى امرأة فوقعت في نفسه إلى أن يأتي امرأته أو جاريته فيواقعها (ص21–24)`,
    items: [
    { q: `علاج من رأى امرأة فأعجبته`, p: `22`,
      n: `يستحب لمن رأى امرأة فتحركت شهوته أن يأتي امرأته أو جاريته إن كانت له فليواقعها ليدفع شهوته وتسكن نفسه.`,
      o: NO_O,
      s: `هذا أفضل علاج لغض البصر، وهو الذي أمر به النبي ﷺ في قوله (يا معشر الشباب... فإنه أغض للبصر)؛ فإذا وقع بصره على شيء من الشهوات فليأت امرأته، فإن ذلك يرد ما في نفسه من مرض الشهوة المحرمة.` },
    { q: `خروج المرأة بين الرجال: هل يشترط له الضرورة؟`, p: `22`,
      n: `يستنبط من الحديث أنه ينبغي للمرأة ألا تخرج بين الرجال إلا لضرورة.`,
      o: NO_O,
      s: `الضرورة هنا عند العلماء بمعنى الحاجة، وليست الضرورة الاصطلاحية (كحريق في المنزل)؛ فقد أذن النبي ﷺ للنساء في الخروج لحاجتهن، وكانت أسماء تأتي بعلف فرس الزبير، وكانت النساء تخرج إلى المسجد، وكثير من العلماء يطلق الضرورة ويريد الحاجة.` },
    { q: `معنى (المرأة تقبل في صورة شيطان)، وهيئة خروج المرأة`, p: `22–23`,
      n: `الإشارة إلى الهوى والدعاء إلى الفتنة بها، فهي شبيهة بالشيطان في دعائه إلى الشر. وينبغي للرجل الغض عن ثيابها والإعراض عنها مطلقًا.`,
      o: NO_O,
      s: `المرأة إذا خرجت في هيئة تُعجب من ينظر إليها فمعها شيطان يتوصل بها إلى فتنة الرجال، وكذلك إذا خرجت بغير حاجة فهي في صورة البعيد عن الخير (والشيطان من شطن أي بعد)، ولا يلزم أن تكون جنية، وكلمة (في صورة) أي تشبه. فإذا خرجت فلا بد أن تكون على هيئة شرعية ولحاجة.` },
    { q: `بشرية الأنبياء وميلهم إلى النساء`, p: `23`,
      n: `إنما فعل النبي ﷺ ذلك بيانًا لهم وإرشادًا لما ينبغي أن يفعلوه.`,
      o: `من يمدح الأنبياء بعدم الشهوة وأنه لا رغبة لهم في النساء.`,
      s: `نظر النبي ﷺ إلى تلك المرأة كان النظرة الأولى، وهو بشر حُبب إليه النساء، ولا نقص في ذلك. ومن يمدح الأنبياء بانعدام الشهوة فكلامه باطل (ولقد أرسلنا رسلًا من قبلك وجعلنا لهم أزواجًا وذرية)، وقد كان لسليمان وداود وإبراهيم ويعقوب أكثر من امرأة؛ والعبرة أن يكون ذلك فيما أحل الله.` },
    { q: `طلب الرجل امرأته للوقاع في النهار`, p: `24`,
      n: `لا بأس بطلب الرجل امرأته للوقاع في النهار وغيره وإن كانت مشتغلة بما يمكن تركه؛ لأنه ربما غلبت عليه الشهوة فيتضرر بالتأخير.`,
      o: NO_O,
      s: `أقره، ونبّه إلى أن في الحديث استعمال الكناية والتأدب في ذكر ما يقع بين الرجل وامرأته.` },
    ]
  },
  {
    title: `باب نكاح المتعة وبيان أنه أبيح ثم نسخ ثم أبيح ثم نسخ واستقر تحريمه إلى يوم القيامة (ص24–46)`,
    items: [
    { q: `مراحل إباحة المتعة وتحريمها`, p: `30، 32–37، 41`,
      n: `الصواب المختار أن التحريم والإباحة كانا مرتين: كانت حلالًا قبل خيبر، ثم حرمت يوم خيبر، ثم أبيحت يوم فتح مكة (وهو يوم أوطاس لاتصالهما)، ثم حرمت بعد ثلاثة أيام تحريمًا مؤبدًا إلى يوم القيامة. ولا يجوز أن يقال إن الإباحة مختصة بما قبل خيبر وأن ما كان يوم الفتح مجرد تأكيد للتحريم (كما اختاره المازري والقاضي).`,
      o: `المازري: النهي تكرر توكيدًا أو ليشتهر. القاضي عياض: أباحها يوم الفتح للضرورة ثم حرمها يوم الفتح تحريمًا مؤبدًا. ورُوي الإباحة في حجة الوداع، وعن الحسن أنها ما حلت إلا في عمرة القضاء.`,
      s: `تبويب الباب هو أصح الأقوال: كانت مباحة، ثم نُسخت الإباحة عام خيبر، ثم أُبيحت أيامًا معدودة يوم الفتح، ثم عاد التحريم إلى يوم القيامة. وقول المازري (مجرد تكرار النهي) غير ظاهر، بل الظاهر أنه أذن لهم أيام الفتح بعد النهي الأول في خيبر. ويوم الفتح وأوطاس شيء واحد (وقعت الإباحة في غزوة الفتح، وأوطاس قريبة من حنين، وحنين بعد الفتح بيسير)، ولذلك يذكرها بعض الرواة بيوم أوطاس أو عام الفتح؛ ورواية (زمان الفتح) توضح الروايات الأخرى. أما رواية الإباحة في حجة الوداع فلا تصح، لأنهم حجوا ومعهم نساؤهم فلا حاجة، والذي جرى فيها تأكيد للنهي لاجتماع الناس؛ وما ذُكر من عمرة القضاء لم يثبت. وما نقله النووي عن القاضي ليس هو ما قرره النووي أن التحريم يوم خيبر كان على التأبيد، فالصحيح أنها أبيحت أيامًا فقط يوم الفتح. ولا يبعد أن يحرم الشرع أمرًا ثم يأذن فيه مدة محدودة لعارض وحاجة طارئة ثم يعود التحريم مؤبدًا؛ فالشرع جاء بالتدريج كما في الخمر.` },
    { q: `تضعيف ابن القيم لروايات النهي عن المتعة يوم خيبر`, p: `29، 33، 35، 44`,
      n: `حديث تحريمها يوم خيبر صحيح لا مطعن فيه. وقال بعضهم في رواية سفيان: في الكلام انفصال، والمعنى أنه حرّم المتعة ولم يبين زمن تحريمها، ثم قال: ولحوم الحمر يوم خيبر.`,
      o: `ابن القيم (في زاد المعاد) يضعّف هذه الروايات ويحملها على أنه اختلط على الراوي، وأن النهي يوم خيبر إنما كان عن الحمر الأهلية، والمتعة حُرمت يوم الفتح فقط.`,
      s: `العجيب أن ابن القيم يضعف كل هذه الروايات، وهذا ليس بصحيح؛ فالروايات في منتهى الصحة، واتفق الرواة على تخصيص النهي عن متعة النساء يوم خيبر، والروايات عن غير سفيان صريحة في ذلك. وتضعيف ابن القيم ليس له وجه، إذ فيه تضعيف للثقات لمجرد الوهم والاحتمال مع إمكان الجمع بغير ذلك؛ فأيُّ هؤلاء الرواة وهم؟ يحيى بن يحيى، ومالك، وابن شهاب، وعبد الله والحسن ابنا محمد بن علي عن أبيهما، كلهم ثقات أثبات، فتوهيمهم لمجرد الاحتمال لا يجوز.` },
    { q: `هل أبيحت المتعة يوم الفتح (للضرورة)؟ وهل الزواج من الضرورات؟`, p: `35–36`,
      n: `تحتمل أنه ﷺ أباحها لهم للضرورة بعد التحريم، ثم حرمها تحريمًا مؤبدًا.`,
      o: NO_O,
      s: `كلمة (الضرورة) هنا على الاصطلاح الأوسع في الاستعمال، فكثير من العلماء يستعمل الضرورة بمعنى الحاجة، لا بالمعنى الشرعي الاصطلاحي؛ لأن الزواج أصلًا حاجة متأكدة وليس من الضرورات بالنسبة للشخص الواحد، فقد يعيش الإنسان عمرًا دون زواج، لكنه من الحاجات العامة التي يمتنع أن تُمنع نهائيًا في مجموع الناس (وليستعفف الذين لا يجدون نكاحًا). فالإباحة كانت للحاجة لا للضرورة الشرعية.` },
    { q: `قراءة ابن مسعود (فما استمتعتم به منهن إلى أجل)`, p: `31`,
      n: `قراءة شاذة لا يحتج بها قرآنًا ولا خبرًا، ولا يلزم العمل بها.`,
      o: NO_O,
      s: `هي شاذة لمخالفتها رسم المصحف، والصحيح أن القراءة الشاذة يُحتج بها خبرًا كالحديث؛ لكن هذه منسوخة تلاوةً وحكمًا: فالتلاوة منسوخة بلا نزاع لمخالفتها الرسم، والحكم منسوخ بلا نزاع معتبر لأن الأحاديث صريحة في التحريم إلى يوم القيامة.` },
    { q: `قول زفر: من نكح نكاح متعة تأبّد نكاحه`, p: `31، 37`,
      n: `كأنه جعل ذكر التأجيل من باب الشروط الفاسدة في النكاح فتُلغى ويصح النكاح. وأجمعوا على أنه متى وقع نكاح المتعة الآن حُكم ببطلانه، قبل الدخول أو بعده، إلا ما سبق عن زفر.`,
      o: `زفر: يصح النكاح ويلغو التوقيت.`,
      s: `زفر يجعله نكاحًا صحيحًا والشرط باطلًا، والجمهور على التحريم والبطلان، وأن نكاح المتعة باطل أصلًا لا يصح، ولا يُلغى الشرط فقط بل العقد نفسه ملغي.` },
    { q: `حكم الخلاف في المتعة، ودعوى الإجماع مع خلاف الرافضة`, p: `30، 33، 38، 50`,
      n: `المازري: انعقد الإجماع على تحريمه ولم يخالف فيه إلا طائفة من المستبدعة.`,
      o: `الرافضة يبيحونه.`,
      s: `المستبدعة هم الرافضة الذين يقولون ذلك في زماننا. والصحيح أنه لم يعد هناك خلاف يُعتبر بين أهل العلم: كان خلافًا بين الصحابة، ثم انقرض المخالف وانعقد الإجماع على التحريم مطلقًا؛ فالخلاف فيه غير سائغ، ولذا يحكم القاضي ببطلانه وتبطل الفتوى به، رغم أنه كان خلافًا عند ابن عباس، لصحة الأحاديث وتلقي الأمة لها بالقبول وانعقاد إجماع من يُعتد به بعده. والمعتد به في الخلاف أهل العلم لا أهل البدع الضلال، ولا يُعتد بالرافضة في فقه ولا عقيدة (ومن ضلالاتهم ما يذكرونه من الثواب الهائل للمتعة). وعدّ مذهب الرافضة الإمامية والإباضية من المذاهب الفقهية المعتمدة قول مُحدث باطل أحدثه بعض المتأخرين من الأزهرية، وبداية إشرابه من كلام الشوكاني والصنعاني لنشأتهما الزيدية، والزيدية عامة مذاهبها ليس فيها شذوذ كالرافضة.` },
    { q: `هل يُحد الواطئ في نكاح المتعة؟ وهل الإجماع بعد الخلاف يرفع الخلاف؟`, p: `33، 38`,
      n: `اختلف أصحاب مالك هل يحد؟ ومذهبنا لا يحد لشبهة العقد وشبهة الخلاف. ومأخذه اختلاف الأصوليين: هل الإجماع بعد الخلاف يرفعه ويصير المسألة مجمعًا عليها؟ والأصح عند الشافعية أنه لا يرفعه بل يدوم الخلاف.`,
      o: NO_O,
      s: `قولهم (الإجماع بعد الخلاف لا يرفعه) غير صحيح؛ الصحيح أن الإجماع بعد الخلاف يرفع الخلاف ويجعل المسألة مجمعًا عليها فلا تجوز مخالفته، لحديث (لا تزال طائفة من أمتي ظاهرين على الحق)، فلا يُتصور أن يخلو زمن من قائل بالحق. والظاهر عند الكثيرين أن المتعة لا يُدرأ بها الحد لانعدام الشبهة، لكن مسألة إقامة الحد تُبنى على وجود الشبهة عند الفاعل: فمن يعتقد برأي من يفتيه من أهل البدع بالجواز (كأن يكون من الرافضة، أو نقل له كلام ابن عباس) يُعذر بعدم إقامة الحد عليه، حتى لو قلنا الخلاف غير سائغ، مع استحقاقه العقوبة إن قصّر في طلب العلم الواجب؛ وفي أزمنة الجهل وانتشار البدع قد يكون ذلك عذرًا يمنع الحد. أما إذا علم التحريم ثم أقدم عليه وهو يعلم بطلانه فهو كالمقدم على الزنى، يقام عليه الحد.` },
    { q: `هل خلاف الواحد والاثنين يقدح في الإجماع؟`, p: `39`,
      n: `نقل القاضي الإجماع على صحة النكاح بنية الطلاق مع ذكر خلاف الأوزاعي.`,
      o: `الأكثر على أن خلاف الواحد يقدح في الإجماع.`,
      s: `قول القاضي (أجمعوا) مع ذكر الخلاف لأن أكثر المتقدمين لا يعدون مخالفة الواحد والاثنين ناقضة للإجماع. والصحيح أن خلاف الواحد لا يقدح، لحديث (لا تزال طائفة من أمتي ظاهرين على الحق)؛ فذكر (طائفة) بصيغة الجمع وأقل الجمع ثلاثة، فلا بد من وجود طائفة تقول بالقول، وكذا ابن جرير لا يعد خلاف الواحد. أما عند من يقول إن خلاف الواحد يقدح فهذا الإجماع فيه نظر.` },
    { q: `أنواع الإجماع، وكيف يُنقل الإجماع مع وجود خلاف؟ (فتوى)`, p: `50`,
      n: NO_N,
      o: NO_O,
      s: `إذا نقل الإجماعَ أئمة معتبرون واتفقوا على ذلك في نقلهم، ولم يُعرف مخالف بعد انقراض الخلاف، فهذا كافٍ في نقل الإجماع عند عامة أهل العلم، ولا يلزم التواتر. ونحن لا نكفّر من قال بحل المتعة، وإنما نكفر من خالف الإجماع القطعي المعلوم من الدين بالضرورة. فالإجماع أنواع: (1) قطعي معلوم من الدين بالضرورة: كوجوب الصلوات الخمس وصوم رمضان. (2) قطعي غير معلوم بالضرورة: كإرث الجدة السدس عند غياب الأم، وتحريم الجمع بين المرأة وعمتها وخالتها (وهو شبه معلوم بالضرورة لكن يجهله كثير من الناس في بعض الأزمنة). (3) ظني: نقله الواحد والاثنان من أهل العلم، فهو في حق من لا يعرف له مخالفًا بمنزلة الحديث الذي صححه عالم وضعفه غيره، فإذا صح عند المجتهد لزمه القول به، ولا يجوز مخالفته لمجرد احتمال وجود مخالف، بل علينا أن نبحث عن المخالف الفعلي، فإن لم يوجد فهو إجماع ظني يلزم به الحكم.` },
    { q: `رجوع ابن عباس، وهل تباح المتعة للمضطر؟ (مع حكم الاستمناء)`, p: `28، 37، 44–46، 51`,
      n: `كان ابن عباس يقول بإباحتها، ورُوي عنه أنه رجع عنه. وقال ابن أبي عمرة: إنها كانت رخصة في أول الإسلام لمن اضطر إليها كالميتة والدم ولحم الخنزير.`,
      o: `القول بإباحتها للمضطر كالميتة.`,
      s: `الظاهر أن ابن عباس رجع عن القول بالإباحة المطلقة، لكنه كان يجوزها عند الحاجة الشديدة للمضطر حتى لا يقع في الزنى؛ وكان معذورًا لأنه علم إباحتها أيام الفتح بعد النهي في خيبر، فلعله ظن أنها رخصة، ولم يصح عنده النسخ، وتردد في قبول كلام ابن الزبير لأنه أصغر منه، فلما ثبت لديه رجع عن القول بأنها رخصة للمضطر. لكن حديث سبرة صريح في تأبيد التحريم (ألا إنها حرام من يومكم هذا إلى يوم القيامة)، وهذا خبر، والأخبار لا يدخلها النسخ، فتأبد التحريم نهائيًا. فالصحيح أنه لا يقال لمن خشي الزنى: تزوج متعة، بل لا تحل له المتعة ولا الزنى، وعليه أن يصوم ويتضرع إلى الله ويعتصم به ويصبر. والاضطرار هنا غير ثابت؛ فلم يقل أحد إن الزنى يحل للمضطر، وأمر النكاح ليس من الضرورة التي تبيح المحظور، والضرورة ما يُخشى منه الهلاك. وكذلك الاستمناء باليد: من يجيزه يقول (عند الضرورة) ولا يعني الضرورة الشرعية بل شدة الحاجة، وهو قول غير الجمهور. وفي فتوى: إطلاق جواز الاستمناء خلاف ضعيف، أما تجويزه لمن خشي على نفسه العنت والوقوع في الزنى بهذا الضابط (أهون من الزنى) فخلاف سائغ والجمهور على المنع، وليس معنى السائغ أن يأخذ الأيسر، بل يلزمه قول أوثق أهل العلم عنده، أو ينظر في الدليل إن كان من أهله.` },
    { q: `استدلال ابن مسعود بآية (لا تحرموا طيبات ما أحل الله لكم) على المتعة`, p: `40`,
      n: `فيه إشارة إلى أنه كان يعتقد إباحتها كقول ابن عباس، وأنه لم يبلغه نسخها.`,
      o: NO_O,
      s: `هذا ظاهر جدًا من استدلاله بالآية، ويمكن أن يخفى النسخ على بعض الصحابة.` },
    { q: `التغليظ في الإنكار على المخالف في مسألة لا يسوغ فيها الخلاف (قصة ابن الزبير وابن عباس)`, p: `28–30، 43–44`,
      n: `قوله (إن ناسًا أعمى الله قلوبهم... يعرض بابن عباس). وقوله (لئن فعلتها لأرجمنك بأحجارك) محمول على أنه بلغه الناسخ ولم يبق شك في تحريمها، فإن فعلها بعد ذلك كان زانيًا يُرجم.`,
      o: NO_O,
      s: `كان ابن عباس حاضرًا الخطبة. والمسألة عند ابن الزبير لا يسوغ فيها الخلاف، بل يظهر من كلامه أنه لا يدرأ الحد بمثل هذا الخلاف ولا يراه شبهة لصحة النسخ عنده؛ ففيه دليل على إثبات الخلاف غير السائغ عند الصحابة، وأنه يُغلظ على من خالف في مسألة أُجمع عليها أو ثبت فيها الدليل. ولما كانت المسألة عند ابن عباس مما يسوغ فيه الخلاف أنكر على ابن الزبير. فإذا كانت المسألة يخالف فيها المخالف نصًا من كتاب أو سنة أو إجماعًا ساغ التغليظ في الإنكار، بل قد يصل إلى أبلغ درجاته وهو إقامة الحد؛ وقد نص أحمد على إقامة الحد في شرب النبيذ المختلف فيه، فمن شربه متأولًا لا يُفسَّق ويقام عليه الحد، لأن هذا من باب إنكار المنكر ولو كان صاحبه معذورًا. والمسألة قد يقع اجتهاد في كونها خلافًا سائغًا أو غير سائغ، ومرد ذلك إلى نوع الدليل فيها، سواء كانت عملية أو علمية. ومن أزيلت عنه الشبهة وبلغه التحريم وجب عليه الحد لأنه أقدم على ما يعلم بطلانه. وفيه أدب الرواة: لم يذكروا اسم ابن عباس عند التشديد، وذكروه في الرواية اللينة (مهلًا يا ابن عباس)، ولابن الزبير تغليظ شديد (كما أعمى أبصارهم) لما عمي ابن عباس في آخر عمره؛ وفيه أن ابن عباس ظل يفتي بها زمنًا طويلًا (نحو خمس وعشرين سنة من عهد علي إلى زمن ابن الزبير).` },
    { q: `المهر في نكاح المتعة`, p: `39، 43`,
      n: `المهر الذي أعطاها يستقر لها، ولا يحل أخذ شيء منه وإن فارقها قبل الأجل المسمى، كما يستقر في النكاح المعروف بالوطء ولا يسقط منه شيء بالفرقة بعده. و(رخص لنا أن ننكح المرأة بالثوب) أي بالثوب وغيره مما نتراضى به.`,
      o: NO_O,
      s: `وكذلك في النكاح المعروف، رغم أن الأصل فيه التأبيد، لا يقال إنه إذا طلقها في منتصف المدة أو قبل انتهاء العمر فله شيء من المهر، بل يستقر المهر بمجرد الدخول. والترخيص بالمتعة بشيء من المال هو مهر كان في ذلك الوقت، أما الآن فلا يجوز هذا النكاح بشيء من الأشياء.` },
    { q: `أحكام المتعة: لا ميراث، والفراق بانقضاء الأجل بلا طلاق`, p: `37`,
      n: `اتفق العلماء على أن هذه المتعة كانت نكاحًا إلى أجل، لا ميراث فيها، وفراقها يحصل بانقضاء الأجل من غير طلاق.`,
      o: NO_O,
      s: `وهذا ما زال موجودًا عند الرافضة من جهة الأحكام؛ يقولون إن نكاح المتعة ينتهي بانقضاء الأجل فتحصل به الفرقة دون حاجة إلى طلاق، لأنه يقع ابتداءً على أجل، ولا يورِّثون به كذلك.` },
    { q: `النكاح بنية الطلاق`, p: `38–39`,
      n: `قال القاضي: أجمعوا على أن من نكح نكاحًا مطلقًا ونيته ألا يمكث معها إلا مدة نواها فنكاحه صحيح حلال، وليس نكاح متعة، وإنما نكاح المتعة ما وقع بالشرط المذكور. ولكن قال مالك: ليس هذا من أخلاق الناس. وشذ الأوزاعي فقال: هو نكاح متعة ولا خير فيه.`,
      o: `مالك: كرهه. الأوزاعي: هو نكاح متعة.`,
      s: `مالك عدّه مكروهًا أن ينوي طلاق المرأة. والصحيح قول الجمهور ما لم يكن تواطؤ؛ فإذا كان هناك اتفاق بالشرط الصريح أو بالتواطؤ فهو كالشرط الصريح (المعروف عرفًا كالمشروط لفظًا)، فإذا اتفقا ولم يذكراه في صيغة العقد فهو نكاح متعة، كأن يتزوجها وهو يعلم وهي تعلم أنهما يلتزمان الانفصال بعد مدة، فهو كتوقيت النكاح تمامًا ولا يجوز؛ لأن العبرة بالمقاصد والمعاني لا بالألفاظ فقط. أما ما ذكره الأوزاعي فهو مجرد النية دون تواطؤ، فإذا كانت نية في نفس الرجل لا يُعلمها المرأة ولا يخبرها بها فلا يحرم بها النكاح ولا يصير متعة. وإذا اتفقا على شرط محرم كالتوقيت بطل النكاح، بخلاف الشروط المحرمة الأخرى فيبقى معها صحة العقد ويبطل الشرط، وبعض الشروط ليست محرمة أصلًا كاشتراط ألا يتزوج عليها على الصحيح.` },
    { q: `تعريف زواج المتعة، وزواج المسيار (فتوى)`, p: `33`,
      n: NO_N,
      o: NO_O,
      s: `زواج المتعة هو الزواج المحدد المدة، كمن يتزوج إذا سافر إلى بلد وهو متفق معها أنه عند عودته سوف يطلقها، أو يتزوجها مدة الدراسة. وزواج المسيار نوع آخر: يأتي المرأة بالنهار فقط، فإن كان محدد المدة فهو داخل في نكاح المتعة، وإن كان باشتراط أنه يأتيها نهارًا لا ليلًا ولا ينفق عليها ولا يسكنها ولا يفعل شيئًا من حقوق الزوج إلا أنه يمر عليها، فالزواج صحيح والشروط باطلة (عدم الإنفاق وألا يبيت عندها وألا يسكنها) لأنها تخالف مقتضى العقد.` },
    { q: `نسب الولد في نكاح المتعة (فتوى)`, p: `50`,
      n: NO_N,
      o: NO_O,
      s: `ينسب إلى زوجها الذي حملت منه؛ لأن من يجوّز المتعة من الرافضة، وما كان قديمًا قبل التحريم، لا بد فيه من استبراء الرحم بحيضة، فإذا تبين الحمل يلحق النسب حتى لو فارقها كالمطلقة.` },
    { q: `نهي عمر رضي الله عنه عن المتعة`, p: `40–41`,
      n: `قوله (استمتعنا على عهد رسول الله ﷺ وأبي بكر وعمر) محمول على أن الذي استمتع في عهدهما لم يبلغه النسخ، وقوله (حتى نهانا عنه عمر) يعني حين بلغه النسخ.`,
      o: `يحلو لبعض الزنادقة والجهلة أن يزعموا أن عمر نهى عنها من عنده، ويستدلون بذلك على جواز أن يشرع الحاكم ما يشاء، أو أن الحكم بغير ما أنزل الله لا يكفّر.`,
      s: `ليس أن عمر نهى عن المتعة من قبل نفسه أو باجتهاده (كما نهى عن متعة الحج باجتهاده)، بل نهى عن متعة النساء لتحريم رسول الله ﷺ لها، ولذلك فرّق الناس بين الأمرين: فالتُزم نهي عمر في متعة النساء وتُرك نهيه في متعة الحج. وليس عمر يلزم الناس بأشياء من عنده، ولا يُظن أنه يحكم بغير ما أنزل الله؛ بل كان يجتهد وينظر في الأدلة، وهو الملهم المحدَّث، فلا ينازع في ذلك إلا مجادل بالباطل أو زنديق أو جاهل. وإلزامه بالطلاق الثلاث بلفظ واحد اجتهاد منه عقوبة وزجرًا لهم (وهو الأولى)، أو لأنه كان عنده ناسخ لم يعلمه الجمهور؛ أي منعهم من مباح ليزجرهم عن محرم. وإسقاطه حد السرقة عام المجاعة لعدم استيفاء شروط الحد، فمن سرق جائعًا ليسد ضرورته فليس بسارق يقام عليه الحد، فلا يقال عطّل الحدود. ولا يستدل بذلك من يبيح ما حرم الله كالزنى (حرية شخصية) أو يسوي الذكر بالأنثى في الميراث بزعم أنهم مثل عمر، نعوذ بالله.` },
    { q: `حكم لحوم الحمر الأهلية`, p: `45`,
      n: `تحريمها مذهبنا ومذهب العلماء كافة إلا طائفة يسيرة من السلف؛ فقد رُوي عن ابن عباس وعائشة وبعض السلف إباحته، ورُوي عنهم تحريمه، ورُوي عن مالك كراهته وتحريمه.`,
      o: `المشهور عند المالكية حمل النهي على الكراهة، لأن آية (قل لا أجد فيما أوحي إلي محرمًا...) صارفة عندهم.`,
      s: `الصحيح أن دليل تحريم الحمر الأهلية مخصص لمفهوم الآية؛ فإن سُمي نسخًا فنحن نقول بصحة نسخ الكتاب بالسنة الصحيحة المتلقاة بالقبول، وإن سمي تخصيصًا فهو أولى بالجواز (والجمهور على أن السنة تخصص القرآن). والخلاف هنا لفظي، فالتخصيص للعام الذي عُمل به مدة ثم جاء المخصص نوع من النسخ في الحقيقة. فالقول بالكراهة غير صحيح، والحمل عليها ليس حملًا صحيحًا خصوصًا مع الروايات الثابتة أن النبي ﷺ أمر بإراقة القدور وكسرها، ولا يمكن إفساد المال مع الجوع لأجل الكراهة. (وسئل الشيخ: هل كراهة المالكية من جنس الكراهة الشرعية؟ فقال: نحن ننقل قولهم، والقول الثاني عندهم أنها كراهة تحريم، فهما قولان عند المالكية، لكن المتأخرين يذكرون كراهة التنزيه).` },
    { q: `تصدير مسلم الباب بروايات أئمة آل البيت`, p: `45`,
      n: NO_N,
      o: NO_O,
      s: `صدّر الإمام مسلم الباب بالروايات بإسناد أئمة أهل البيت: عبد الله والحسن ابني محمد بن علي عن أبيهما عن علي بن أبي طالب؛ ففيه تصريح بتخطئة من يقول بجواز نكاح المتعة، ورد على الرافضة الذين ينسبون جوازها إلى أئمة آل البيت.` },
    { q: `(وسيدًا وحصورًا) ليحيى، و(إلا ما حرّم إسرائيل على نفسه) ليعقوب، مع إنكار النبي ﷺ على النفر الذين تركوا النكاح (فتوى)`, p: `33`,
      n: NO_N,
      o: `بعض العلماء: الحصور هو الذي لا يأتي النساء أصلًا.`,
      s: `هذا شرع خاص بمن قبلنا، فالأنبياء لا يصنعون شيئًا بغير إذن الله، فأذن الله ليعقوب في تحريم ما حرمه على نفسه قبل نزول التوراة. والصحيح أن الحصور هو الذي يمنع نفسه من الحرام، وليس ترك النساء صفة مدح؛ والمشهور عند أهل الكتاب أن يحيى لم يتزوج، فربما كان ذلك انشغالًا بالدعوة وإقامة المعوج من بني إسرائيل وليس مقصودًا، ولو كان مقصودًا فهو شرع لهم، وقد أتى شرعنا بخلافه فلا بد من تقديمه؛ فإما أنه أمر غير مقصود (لعدم وجود الباءة، أو للانشغال بعبادات كالدعوة وطلب العلم ولم يكن عنده مؤنة النكاح)، وإما أنه خاص بهم.` },
    { q: `امتناع الزوجة عن الإنجاب واستعمال موانع الحمل بغير رضا الزوج (فتوى)`, p: `34`,
      n: NO_N,
      o: NO_O,
      s: `استعمال وسائل منع الحمل لا بد أن يكون برضا الزوجين معًا؛ فلا يجوز أن يُرغم الزوج زوجته عليه لأن لها حقًا في الولد، ولا يجوز للزوجة أن تفعله بغير إذن الزوج لأن له حقًا في الولد بلا شك، وأصل هذا الباب العزل فإنه يكون بإذنها. فامتناعها عن الحمل بغير موافقته محرم عليها، وعليه أن ينصحها.` },
    { q: `تعاطي المرأة أدوية لتحديد النسل أو للمباعدة بين الأولاد (فتوى)`, p: `34`,
      n: NO_N,
      o: NO_O,
      s: `إن كان لخوف الفقر فهو محرم وسوء ظن بالله، وإن كان بغير إذن الزوج فهو محرم أيضًا، وإن كان لمرض قاله الأطباء جاز، وإن كان لمجرد التعب والوهن المعتاد فهو مكروه؛ فليس هناك (فترة استراحة) مشروعة، فلو قدر الله لها أن ترضع فتمتنع من الحمل فذاك، أما تعمد أخذ وسائل منع الحمل لتطويل الفترة بين المولودين فداخل في الأحكام المذكورة.` },
    { q: `عقد النكاح إذا كان ولي المرأة يسب الدين أو لا يصلي (فتوى)`, p: `34`,
      n: NO_N,
      o: NO_O,
      s: `إن كان يسب الدين فالعقد باطل لأنه ليس بمسلم، فلا يصح عقده ولا بد من تجديده. وإن كان لا يصلي تكاسلًا فعقده صحيح.` },
    ]
  },
  {
    title: `باب تحريم الجمع بين المرأة وعمتها أو خالتها في النكاح، وسؤال المرأة طلاق أختها (ص46–53)`,
    items: [
    { q: `العمة والخالة (الحقيقية والمجازية) في تحريم الجمع`, p: `47`,
      n: `يحرم الجمع بين المرأة وعمتها وخالتها، سواء كانت عمة وخالة حقيقية (أخت الأب وأخت الأم) أو مجازية (أخت أبي الأب وأبي الجد وإن علا، أو أخت أم الأم وأم الجدة)، بإجماع العلماء.`,
      o: `طائفة من الخوارج والشيعة: يجوز، لعموم (وأحل لكم ما وراء ذلكم)، وخصها الجمهور بالأحاديث.`,
      s: `بل هي عمة حقيقة لأنها أخت أب وإن كان جد أب؛ قال تعالى عن يوسف (واتبعت ملة آبائي إبراهيم وإسحاق ويعقوب)، فالجد أب في كتاب الله، وكذا كل من علا من الآباء. والجدة أم (فهي ترث لكونها أمًا عند غياب الأم المباشرة)، فأختها خالة. والصحيح جواز تخصيص عموم القرآن بخبر الواحد.` },
    { q: `الجمع بين المرأة وعمتها أو خالتها في الوطء بملك اليمين`, p: `48`,
      n: `حرام عند العلماء كافة كالنكاح. وعند الشيعة مباح، ويبيحون الجمع بين الأختين بملك اليمين.`,
      o: `الشيعة.`,
      s: `معناه أنه إذا ملك امرأتين بينهما هذه العلاقة، أو تزوج امرأة واشترى خالتها، فلا يجوز أن يجمع بينهما في الوطء؛ فتبقى الأخرى على ملكه ولكن لا يجامعها حتى يطلق هذه أو تموت عنه.` },
    { q: `المحرمات في الآية محرمات بالنكاح وبملك اليمين`, p: `48`,
      n: `جميع المذكورات في الآية محرمات بالنكاح وبملك اليمين جميعًا.`,
      o: NO_O,
      s: `مثاله: من ملك أخته (كانوا عبيدًا ثم أُعتق هو وملك مالًا فاشترى أخته) فلا يجوز أن يطأها بإجماع العلماء، وكذا في المصاهرة؛ مع أنها تعتق عليه بمجرد الملك عند جمهور العلماء.` },
    { q: `عقد النكاح على أمته`, p: `48`,
      n: `(والمحصنات من النساء إلا ما ملكت أيمانكم): ملك اليمين يحل وطأها لا نكاحها، فإن عقد النكاح عليها لم يجز لسيدها.`,
      o: NO_O,
      s: `لا يحل نكاحها لأنها مملوكة، بل الصحيح أنه يجوز أن يعتقها ويتزوجها.` },
    { q: `الجمع بين بنتي العم أو بنتي الخالة`, p: `49`,
      n: `جائز عند الشافعية وعند العلماء كافة، إلا ما حكاه القاضي عن بعض السلف أنه حرّمه. ودليل الجمهور (وأحل لكم ما وراء ذلكم).`,
      o: `بعض السلف: يحرم.`,
      s: `أي بين بنت عمه وبنت عمه الآخر، وبين بنت خالته وبنت خالته الأخرى. والذين حرّموا قاسوا قياسًا غير صحيح، إذ قالوا إن ذلك يؤدي إلى قطيعة الرحم.` },
    { q: `الجمع بين زوجة الرجل وبنته من غيرها`, p: `49، 65`,
      n: `جائز عند الشافعية ومالك وأبي حنيفة والجمهور؛ لقوله تعالى (وأحل لكم ما وراء ذلكم).`,
      o: `الحسن وعكرمة وابن أبي ليلى: لا يجوز.`,
      s: `صورتها: رجل كانت له زوجة وله بنت من امرأة أخرى، ثم مات أو طلق؛ فهل يجوز لرجل آخر أن يجمع بينهما؟ الذين منعوا - وهو أيضًا قول الإمام أحمد - قالوا: لا يجوز الجمع بين كل امرأتين بينهما قرابة، لو كان أحدهما رجلًا لحرمت عليه تحريمًا مؤبدًا، قياسًا على الجمع بين الأختين. وهذا قياس له وجه وقوي، وهذا القول عندي أقرب (قال: وقول أحمد هو الراجح)؛ فلو كانت البنت ابنًا لحرمت عليه زوجة أبيه (ولا تنكحوا ما نكح آباؤكم)، فالعلاقة بينهما تشبه العلاقة بين المرأة وعمتها وخالتها في تأبيد التحريم، وهذا الوجه من جهة القياس وجه قوي.` },
    { q: `إعراب (ولا تسأل المرأة طلاق أختها) ومعناه`, p: `52`,
      n: `يجوز في (تسأل) الرفع والكسر: الأول على الخبر الذي يراد به النهي، وهو المناسب لقوله (لا يخطب ولا يسوم)، والثاني على النهي الحقيقي. ومعناه: نهي المرأة الأجنبية أن تسأل الزوج طلاق زوجته وأن ينكحها، ويصير لها من نفقته ومعروفه ومعاشرته ما كان للمطلقة، فعبر عن ذلك باكتفاء ما في الصحفة مجازًا.`,
      o: NO_O,
      s: `هو بالرفع، إذ لو كانت نهيًا لكانت (لا يخطبْ) بالسكون، وأما ما ورد (لا يخطبُ ولا يسومُ) فهي على الرفع، وكذا (ولا تسألُ)، ويمكن أن تحمل على الكسر لأن السكون يخفف إلى الكسر مع الألف واللام لأنه مجزوم بلا الناهية. ومعنى (لتكتفئ صحفتها): أن تأخذ ما في إناء أختها مما كان يعطيه الزوج لزوجته الأولى من عشرة ونفقة وغير ذلك.` },
    { q: `المراد بأختها: هل يدخل فيه طلب طلاق الكافرة؟ وسؤال الزوجة الأولى طلاق الثانية`, p: `52–53`,
      n: `المراد بأختها غيرها، سواء كانت أختها من النسب، أو أختها في الإسلام، أو كافرة.`,
      o: `من يرى أن المقصود الأخت في الإسلام فقط.`,
      s: `أما (أختها في الإسلام) فظاهرة، وأما (أو كافرة) فلأنهم قالوا إن التقييد بالأخت خرج مخرج الغالب فلا مفهوم له، فإذا كان الرجل المسلم قد تزوج يهودية أو نصرانية فلا يجوز للمسلمة أن تقول له طلقها وتزوجني، فلا تسأل المرأة طلاق امرأة قط؛ لأن ترغيب الرجل في طلاق امرأته ووعده بالزواج ونحو ذلك يؤدي إلى فساد كبير، لذلك نهى الشرع عنه. ويدخل في المعنى الأصلي (لا تسأل المرأة طلاق أختها لتكتفئ صحفتها ولتنكح): أي فلتتزوج دون أن تشترط عليه طلاق الأولى، ولتكن زوجة ثانية، فإنما لها ما كتب الله لها؛ وفيه إثبات الإيمان بالقدر (وقد ذكره البخاري مستدلًا به على ذلك). ويدخل فيه كذلك سؤال الزوجة الأولى طلاق الثانية (طلقها حتى أرجع إليك، أو حتى لا أختلع، أو حتى أظل معك)، فالمعنى واحد، وهذا يقع فيه كثير من النساء حتى من الأخوات، وكذا اشتراط (لا تتزوجني حتى تطلق الأولى)؛ فكل هذا منافٍ للإيمان بالقضاء والقدر ولقوله ﷺ (لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه). فإذا وقع وتزوج امرأتين فلكل واحدة ما قُدّر لها.` },
    { q: `هل طلب الزوجة ألا يتزوج عليها داخل في النهي؟`, p: `53`,
      n: NO_N,
      o: NO_O,
      s: `مسألة منعه من أن يتزوج عليها: إن كان شرطًا عند العقد فهو معتبر، وإلا فلا يلزمه. ولا تدخل في هذا النهي؛ لأنها صاحبة الصحفة ولم تطلب طلاق أحد.` },
    { q: `هل يمكن أن تكون العصمة بيد المرأة؟ (فتوى)`, p: `50–51`,
      n: NO_N,
      o: `الحنفية - وبه يأخذ القانون - أنه إذا اشترط ذلك عند العقد يظل طوال فترة العقد لا يسعه أن يلغيه.`,
      s: `المرأة يمكن أن تُوكَّل في طلاق نفسها، وليس أن العصمة في يدها بمعنى أن تملك أمر الطلاق ويسقط حق الزوج؛ فالطلاق حق للزوج أعطاه الله له لا يسقط بحال ولو أسقطه هو، لكنه يمكن أن يوكل فيه غيره، ومنهم امرأته. وليس معنى العصمة في يدها أن تقول لزوجها (أنت طالق) فلو قالت ذلك لم يقع شيء، بل تقول (أنا طالق) أو (طلقت نفسي منك) بالتوكيل الذي أعطاه لها. وهل يلغى هذا التوكيل بإلغائه ولو كان عند العقد؟ فيه خلاف، والصحيح أن التوكيل جائز يُلغى بإلغائه متى أُلغي، ولا يسقط حقه في الطلاق، وإنما يجعل لها الحق في أن تطلق نفسها.` },
    { q: `تغسيل الرجل أمه بوصية منها (فتوى)`, p: `51`,
      n: NO_N,
      o: NO_O,
      s: `صح الغسل ولكنه أساء بلا شك، ويُنكر عليه؛ لأن النبي ﷺ ما غسّل ابنته لما ماتت، وإنما قال للنسوة (اغسلنها ثلاثًا أو خمسًا...) وأعطاهن حقوه فقال أشعرنها إياه، ولو كان خيرًا لفعله ﷺ. فالرجل يمكن أن يغسّل زوجته، أما أمه أو بنته فلا؛ لأن ذلك يؤدي إلى كشف ما لا يجوز كشفه من العورة، ويمكن أن يقال بالكراهة على أساس أن النسوة في ذلك كالرجل، ولكن هذا خلاف السنة.` },
    ]
  },
  {
    title: `باب تحريم نكاح المحرم وكراهة خطبته (ص53–59)`,
    items: [
    { q: `حكم نكاح المحرم وإنكاحه`, p: `55`,
      n: `قال مالك والشافعي وأحمد وجمهور العلماء من الصحابة فمن بعدهم: لا يصح نكاح المحرم، واعتمدوا أحاديث الباب.`,
      o: `أبو حنيفة والكوفيون: يصح نكاحه لحديث قصة ميمونة (تزوجها النبي ﷺ وهو محرم).`,
      s: `نعم، لا يجوز ولا يصح؛ فلو تزوج المحرم أو زوّج وقع النكاح باطلًا.` },
    { q: `الجواب عن حديث ابن عباس في زواج النبي ﷺ ميمونة وهو محرم`, p: `55–56`,
      n: `أجاب الجمهور بأجوبة: أصحها أنه تزوجها حلالًا كما رواه أكثر الصحابة، ولم يروِ أنه تزوجها محرمًا إلا ابن عباس، وروت ميمونة وأبو رافع أنه تزوجها حلالًا وهم أعرف بالقصة وأضبط. الثاني: تأويله على أنه تزوجها في الحرم وهو حلال. الثالث: أنه تعارض القول والفعل، والصحيح ترجيح القول لأنه يتعدى إلى الغير والفعل قد يكون مقصورًا عليه. الرابع: أن النكاح في الإحرام من خصائصه ﷺ (وهو أصح الوجهين عند الشافعية)، والثاني: أنه حرام في حقه كغيره.`,
      o: NO_O,
      s: `(أضبط) أي في هذه المسألة. ومعنى الجواب الثالث أنها واقعة عين قد تحتمل الخصوصية. والأصل عدم الخصوصية، فطالما أمكن الجمع بطريقة أخرى فهو مقدم؛ والنبي ﷺ تزوجها في أرض الحرم. والصحيح أن ابن عباس إن قصد أنه تزوجها حال إحرامه فقد أخطأ؛ لأن صاحبة القصة ميمونة أدرى، وقد روت أنه تزوجها وهو حلال، وكذا السفير بينهما أبو رافع. أما إن قصد بقوله (وهو محرم) أنه كان في أرض الحرم فالمعنى صحيح ولا يُحتاج إلى التخطئة. ولا مانع أن يروي الصحابي شيئًا يظنه صحيحًا فيتبين خطؤه، وذلك لا يقدح في سائر رواياته؛ فنحن لا ندّعي العصمة للصحابة فضلًا عن غيرهم، ولكن كما قبلنا شهادة الشهود مع احتمال الخطأ والكذب، فلابد أن نقبل رواية الرواة لأن هذا الاحتمال مرجوح، ويجب قبولها ما لم يأت ما هو أصرح منها وأوضح، فهنا تركنا رواية ابن عباس لوجود ما هو أصرح وأوضح.` },
    { q: `معنى (ولا يُنكِح)، ومراتب الولاية الخاصة والعامة في النكاح`, p: `56`,
      n: `معناه: لا يزوِّج امرأة بولاية ولا وكالة؛ لأنه لما مُنع في مدة الإحرام من العقد لنفسه صار كالمرأة فلا يعقد لنفسه ولا لغيره. وظاهر العموم أنه لا فرق بين أن يزوّج بولاية خاصة كالأب والأخ والعم ونحوهم، أو بولاية عامة وهو السلطان والقاضي ونائبه، وهذا هو الصحيح عند الشافعية وبه قال جمهورهم.`,
      o: NO_O,
      s: `(لا يُنكِح) أي لا يُطلب منه تزويج امرأة من أوليائها بولاية ولا وكالة؛ فلا يظن البعض أن المرأة هي التي توكِّل، بل وليها هو الذي يوكِّل. والولاية الخاصة في حكم القرابة والعصبة، وهي التي قال عنها النبي ﷺ (لا نكاح إلا بولي)، وفي حديث عائشة (السلطان ولي من لا ولي له)، و(البكر يستأذنها أبوها). فأبوها وليها، ثم يليه باقي العصبات: الجد (وإن كان البعض يقدم الابن، لكن لأن الجد أب فهو مقدم في هذا المقام)، ثم الابن، ثم الأخ الشقيق، ثم ابن الأخ الشقيق، ثم العم الشقيق، ثم ابن العم الشقيق، ثم العم غير الشقيق، ثم ابن العم غير الشقيق. أما الولاية العامة فتكون لمن فقدت وليها، أو عضلها وليها فمنعها من التزويج فتسقط ولايته بسبب فسقه في حقها ومنعه لها، أو تواطأ الأولياء على ذلك، أو كان الولي غير صالح أو غير موجود. وهل تنتقل الولاية حينئذ إلى الولي الأبعد أم إلى السلطان مباشرة؟ الصحيح أنها تنتقل إلى الولي الأبعد، فإن امتنعوا انتقلت إلى السلطان أو من يقوم مقامه كالقاضي ونائب السلطان، فإن عُدم كل ذلك فعالم المحلة أو عدل من المسلمين إن لم يتيسر إلا ذلك؛ وهذا كله ولاية لا وكالة.` },
    { q: `هل يجوز للمحرم أن يزوِّج بالولاية العامة (القاضي والأمير)؟`, p: `57`,
      n: `قال بعض الشافعية: يجوز أن يزوج المحرم بالولاية العامة؛ لأنها يستفاد بها ما لا يستفاد بالخاصة.`,
      o: NO_O,
      s: `معناه أنه إذا كان قاضيًا أو حاكمًا أو أميرًا جاز أن يزوِّج وهو محرم. والصحيح أنه لا يجوز، لعموم الحديث ولا مخصِّص.` },
    { q: `ولاية المسلم على الذمية في النكاح`, p: `57`,
      n: `يجوز للمسلم تزويج الذمية بالولاية العامة دون الخاصة.`,
      o: NO_O,
      s: `بمعنى أنه لو أسلم وله أخت ما زالت نصرانية فهو لا يزوجها على نصرانيتها (بالولاية الخاصة)، والذي يظهر أنه يجوز أن يزوجها لمسلم. وأما الولاية العامة فالسلطان يزوجها على كل حال لأنه لا ولي لها، فإذا أسلمت المرأة وأولياؤها كفار زوجها السلطان أو القاضي أو من يقوم مقامه؛ لأنهم لا يراعون لكفرهم حظها وحقها. فالولاية العامة يستفاد بها ما لا يستفاد بالخاصة في مثل هذا الموطن، فولاية السلطنة أعم من جهة وأخص من جهة. وإذا كان قاضي البلد أو حاكمه يرى مذهب من يرى تزويج المرأة نفسها فامتنع من التزويج، قام مقامه غيره من أهل العلم.` },
    { q: `بطلان عقد النكاح إذا كان أحد أطرافه محرمًا (الزوج، الزوجة، الولي، الوكيل)`, p: `57`,
      n: `النهي عن النكاح والإنكاح في حال الإحرام نهي تحريم، فلو عقد لم ينعقد، سواء كان المحرم الزوج أو الزوجة أو العاقد لهما بولاية أو وكالة، حتى لو كان الزوجان والولي محلين ووكّل الولي أو الزوج محرمًا لم ينعقد.`,
      o: NO_O,
      s: `(بولاية) أي ولاية الولي على الزوجة، أو الولاية على الصغير فيجوز للأب أن يزوج ابنه الصغير إذا رأى المصلحة. (أو وكالة) أن يكون البالغ الرشيد حاضرًا ويوكل غيره؛ فإن كان محرمًا لم يصح توكيله، ولا يجوز أن يوكل المحرم رجلًا غير محرم في تزويجه، لأنه داخل في عموم (لا يَنكح) أي لا يتزوج لا بنفسه ولا بوكالة غيره. ومثاله: إذا كان أبوه في عمرة فأراد أن يوكله احترامًا له فوكله وقع العقد باطلًا، لأن المحرم لا يَنكح ولا يُنكِح.` },
    { q: `خطبة المحرم: هل النهي للتحريم أم للتنزيه؟`, p: `58`,
      n: `قوله ﷺ (ولا يخطب) نهي تنزيه ليس بحرام.`,
      o: NO_O,
      s: `لم يذكر النووي سببًا لصرف الحديث عن ظاهره، والصحيح أنه محرم، إذ لم يدل دليل على جواز الخطبة للمحرم، والنص واحد (لا يَنكح المحرم ولا يُنكِح ولا يخطب)، فلماذا يُحمل أوله على التحريم وآخره على التنزيه بلا دليل؟ إلا لمجرد القول بأنه من باب الأدب، وهذا ليس بصحيح؛ فالسياق واحد فلا بد أن يكون الحكم واحدًا، والنهي ظاهره التحريم في الجميع.` },
    { q: `شهادة المحرم على عقد النكاح`, p: `58`,
      n: `يكره للمحرم أن يكون شاهدًا في نكاح عقده المحلون. وقال بعض الشافعية: لا ينعقد بشهادته لأن الشاهد ركن في عقد النكاح كالولي، والصحيح الذي عليه الجمهور انعقاده.`,
      o: `بعض الشافعية: لا ينعقد.`,
      s: `لم يرد دليل على منع شهادة المحرم، فالصحيح أن شهادته تصح والعقد صحيح. وما ذُكر من أن الشاهد ركن في العقد معنى صحيح (فالولي ركن والشهادة ركن)، لكن ليس فيه دليل على منع شهادة المحرم، ولذا يجوز شهادة المحرم على النكاح.` },
    { q: `قول أبان (ألا أراك عراقيًّا جافيًا): هل هو ذم لأهل العراق؟`, p: `59`,
      n: `قال القاضي: (عراقيًا) إشارة إلى أنه آخذ بمذهب أهل الكوفة في جواز نكاح المحرم، فيصح (عراقيًا) أي آخذًا بمذهبهم في هذا، جاهلًا بالسنة.`,
      o: NO_O,
      s: `ليس في هذا ذم للعراقيين مطلقًا، ولكن في مسألة خالفوا فيها دليلًا.` },
    ]
  },
  {
    title: `باب تحريم الخطبة على خطبة أخيه حتى يأذن أو يترك (ص51، 59–65)`,
    items: [
    { q: `متى تحرم الخطبة على خطبة أخيه؟`, p: `51، 61`,
      n: `هذه الأحاديث ظاهرة في تحريم الخطبة على خطبة أخيه، وأجمعوا على تحريمها إذا كان قد صُرّح للخاطب بالإجابة، ولم يأذن، ولم يترك.`,
      o: NO_O,
      s: `ظاهر الحديث تحريم خطبة الرجل على خطبة أخيه إذا صرّحوا له بالقبول؛ فيحرم على أي خاطب آخر أن يتقدم طالما قبل الخطبةَ أهلُ المرأة أو وليها، أما إذا رفضت هي أو رفض وليها فله أن يتقدم. ثم قال: فإذا كان هذا في الخطبة قبل الزواج، فكيف بتخبيب المرأة على زوجها وترغيبها في الطلاق بعد وقوع الزواج؟ فهو أغلظ بلا شك، ومن يخبب امرأة على زوجها ويأمرها بفراقه أو بسوء عشرته حتى تطلب الطلاق وتطلق فهو ملعون، كما قال النبي ﷺ (ليس منا من خبّب امرأة على زوجها، أو عبدًا على سيده).` },
    { q: `إذا خطب على خطبة أخيه وتزوج: هل يفسخ النكاح؟`, p: `61–62`,
      n: `لو خطب على خطبته وتزوج والحالة هذه عصى، وصح النكاح ولم يفسخ، هذا مذهبنا ومذهب الجمهور.`,
      o: `داود: يفسخ النكاح. وعن مالك روايتان كالمذهبين. وقال جماعة من أصحاب مالك: يفسخ قبل الدخول لا بعده.`,
      s: `الصحيح قول الجمهور؛ لأن هذا النهي لا يقتضي الفساد لأنه نهي عن وصف خارج عن العقد. أما النهي عن وصف لازم للعقد أو عن نكاح هو في نفسه منهي عنه (كالجمع بين المرأة وعمتها وخالتها) فهو نهي في وصف لازم للعقد أو في جزء من أجزائه، وهو أن المرأة المعقود عليها منهي عن التزوج بها. أما هنا فالأمر الخارج هو الخطبة السابقة، والمقصود أنه إذا خطب على خطبة أخيه وقد فسخوا الخطبة من أجل تقدمه وعقدوا النكاح، فهذا العقد قد استوفى شروطه ولا يوجد ما يدل على بطلانه، والنهي ليس عن هذا النكاح بل عن وصف خارج، فيُنهى عنه ويؤمر بتركه ولكن لا يبطل العقد إذا وقع. أما مذهب داود فيجعل كل نهي يقتضي الفساد مطلقًا، فقال: زواج بُني على أمر فاسد فيكون فاسدًا، وهذا يحتاج إلى دليل مستقل. وأما تفرقة أصحاب مالك بين ما قبل الدخول وما بعده مراعاة للمصلحة فليست بظاهرة؛ فإن كان النكاح باطلًا ودخل بها فهو لا يصحح وهو وطء بشبهة يلزم التفريق بينهما، وإن كان صحيحًا فهي امرأته قبل الدخول وبعده، فعلى أي الوجهين لا يستقيم قياسًا، وإنما قالوا ذلك لأجل المصلحة والاستحسان لا بناء على قياس أو دليل.` },
    { q: `إذا عُرِّض للخاطب بالإجابة ولم يُصرَّح`, p: `62`,
      n: `إذا عُرّض له بالإجابة ولم يُصرّح ففي تحريم الخطبة على خطبته قولان للشافعي، أصحهما: لا يحرم.`,
      o: `قال بعض المالكية: لا يحرم حتى يرضوا بالزوج ويُسمى المهر.`,
      s: `التعريض كأن يقال له: إنك لرجل صالح، وسوف ننظر في أمرنا، ونحو ذلك دون تصريح بقبول الخطبة. وقول بعض المالكية معناه أن تسمية المهر هي الحد الفاصل، والصحيح أن الحد الفاصل هو قبول الخطبة حتى يترك أو يأذن؛ فإذا صُرّح له بالقبول فلا يجوز لغيره أن يخطب ولو لم يسموا المهر ولم يتفقوا على التفاصيل.` },
    { q: `الاستدلال بحديث فاطمة بنت قيس (خطبني أبو جهم ومعاوية... فخطبها لأسامة)`, p: `62–63`,
      n: `استدلوا بحديث فاطمة على أن التحريم إنما هو إذا حصلت الإجابة. وقد يعترض بأنه لعل الثاني لم يعلم بخطبة الأول، وأما النبي ﷺ فأشار بأسامة لا أنه خطب له.`,
      o: NO_O,
      s: `هذا استدلال صحيح. أما الاعتراض فمردود: فالنبي ﷺ قد علم بخطبتيهما وخطبها لأسامة، بل صرّح وقال لها (انكحي أسامة بن زيد)، أي تزوجي أسامة، فأي شيء أكثر من ذلك؟!` },
    { q: `متى يُعد الخاطب تاركًا للخطبة؟`, p: `63`,
      n: `اتفقوا على أنه إذا ترك الخطبة رغبة عنها وأذن فيها جازت الخطبة على خطبته، وقد صُرّح بذلك في هذه الأحاديث.`,
      o: NO_O,
      s: `إذا ترك الخطبة ولم يُتمم الزواج الآن لأنه يبحث عن إكمال المهر أو ما اتُّفق عليه، وهو ما زال على نية إكمال الزواج ولم يرغب عنه، فلا يسمى تاركًا في هذه الحالة.` },
    { q: `الخطبة على خطبة الكافر`, p: `63`,
      n: `قال الخطابي وغيره: ظاهره اختصاص التحريم بما إذا كان الخاطب مسلمًا، فإن كان كافرًا فلا تحريم، وبه قال الأوزاعي. وقال جمهور العلماء: تحرم الخطبة على خطبة الكافر أيضًا، ولهم أن يجيبوا بأن التقييد بأخيه خرج على الغالب فلا يكون له مفهوم، كقوله تعالى (ولا تقتلوا أولادكم من إملاق) و(وربائبكم اللاتي في حجوركم).`,
      o: `الجمهور: تحرم.`,
      s: `قول الأوزاعي من جهة الدليل أقوى وأظهر. وصورته: مسلم يخطب يهودية أو نصرانية مخطوبة لكافر [ولا يقال ذمية لأن المجوسية ذمية أيضًا، ويمكن أن يتزوج كافرة حربية ويُدخلها البلد بأمان]. فظاهر الحجة مع الأوزاعي؛ لأن الحديث قال (ولا يخطب على خطبة أخيه) وذكر جملة من حقوق الأخوة الإيمانية، فدل على أن الحكم لوجود وصف الأخوة الإيمانية. وهناك فرق في هذا الباب وهو النصيحة للكتابية التي يجوز نكاحها أن تتزوج المسلم، فالمصلحة لها في ذلك؛ فلا يلزم أن يقاس الحديث على القول الآخر بأنه خرج مخرج الغالب، فالأصل أن ظاهره تحريم الخطبة على خطبة المسلم خاصة. وأما (ولا تقتلوا أولادكم من إملاق) فلا يقتلهم من إملاق ولا من غيره. وأما (وربائبكم اللاتي في حجوركم) فالربيبة التي ليست في حجره لا يجوز له أن يتزوجها؛ فلو كان للمرأة بنت عند أبيها أو أهلها ولم تكن في حجره حرمت عليه عند عامة العلماء.` },
    { q: `الخطبة على خطبة الفاسق`, p: `63–64`,
      n: `الصحيح الذي تقتضيه الأحاديث وعمومها أنه لا فرق بين الخاطب الفاسق وغيره.`,
      o: `قال ابن القاسم المالكي: تجوز الخطبة على خطبة الفاسق.`,
      s: `(قول ابن القاسم) لأجل مصلحة المرأة كما ذكرنا في أمر الكافر، ولا شك أن الفاسق أهون من الكافر، وهو في النهاية أخو المسلم قد دخل في العموم (فتحرم الخطبة على خطبته).` },
    { q: `إذا أجيب الخاطب الأول، ثم خطب آخر أفضل منه دينًا وخلقًا لا يعلم بخطبة الأول: هل يرجع الأولياء؟ (فتوى)`, p: `64`,
      n: NO_N,
      o: NO_O,
      s: `لا شك أن هذا الأمر وقع بسبب غير شرعي وهو معذور فيه، لكن ينبغي أن يُعلموه بخطبة الأول ولا يتركوه يستمر في الخطبة. ثم إن رأوا بعد ذلك - دون مواطأة معه - أن المصلحة في فسخ الخطبة الأولى فسخوها، فإن تقدم بعد ذلك تقدم. أما أن يواعدوه ويقولوا: هي الآن مخطوبة وسنفسخ خطبتها، فإذا فُسخت فتعال فتقدم، فهذا لا يجوز.` },
    { q: `هل يزوّج الجد مع وجود الأب؟ (فتوى)`, p: `64`,
      n: NO_N,
      o: NO_O,
      s: `إن كان على سبيل الوكالة جاز، وأما مع وجود الأب دون إذنه أو علمه فلا يجوز أن يزوّج الجد. والوكالة لا يلزم فيها توكيل رسمي مكتوب، بل يمكن أن يقول للجد: تفضل اعقد العقد، فهذا توكيل؛ أو أن يقول الصيغة فلانٌ والولي هو الذي أمره بذلك، فلا بأس، وهو توكيل، وليس أن الجد يكون وليًا مع وجود الأب.` },
    { q: `إهمال الأب في الولاية بسبب الخصومة بعد الطلاق، وولاية الخال وأبي الأم (فتوى)`, p: `65`,
      n: NO_N,
      o: NO_O,
      s: `لُحمة النسب لا تنفصل إلا بالكفر والردة، لا بالتقصير في حق الأبناء؛ فلو مات الأب ورثه أولاده ولو لم يربهم، وإذا ماتوا ورثهم كذلك. وكثير من الناس عند الخصومة بين الأم والأب يهملون الأب عمدًا ويجعلون الخال أو الجد أبا الأم وليًا، وهذا لا يصح؛ وإنما الولي الأب ثم الجد ثم الابن ثم الأخ ثم ابن الأخ كما سبق. فليس الخال وليًا إلا عند عدم العصبة، وكذا أبو الأم؛ فإذا عُدم كل الأولياء من العصبة فهو وارث بالرحم من ذوي الأرحام، فهو أقرب، والولاية هنا قرابة فهو أولى من السلطان، خصوصًا في زمن غياب السلطان.` },
    { q: `عضل الولي إذا رضيت المرأة بخاطب كفء وبمهر أقل من مهر المثل (فتوى)`, p: `65`,
      n: NO_N,
      o: NO_O,
      s: `من حقها أن تتنازل عن مهر المثل وأن تقبل بصداق أقل منه، فإذا امتنع أبوها من التزويج كان عاضلًا. لكن له أن يمتنع إذا كان الخاطب فاسقًا غير ديّن؛ أما إن كان عدلًا وعرض مهر المثل أو دونه وقبلت المرأة صاحبة الحق، فليس له أن يعترض، فإن اعترض وامتنع فهو عاضل تسقط ولايته وتنتقل إلى الأبعد. فإن تواطأ الأولياء جميعًا على عدم التزويج وهي تريد الزواج - وهذا حقها - فهي أولى بنفسها. فللولي أن يعترض على أمر الدين، وليس له أن يعترض مطلقًا دون سبب، فإن فعل سقطت ولايته.` },
    ]
  },
  {
    title: `باب تحريم نكاح الشغار وبطلانه (ص65–74)`,
    items: [
    { q: `تفسير الشغار: ممن هو؟`, p: `66–67`,
      n: `الشغار أن يزوج الرجل ابنته على أن يزوجه الآخر ابنته وليس بينهما صداق، وفي الرواية الأخرى بيان أن التفسير من كلام نافع. وأصله في اللغة الرفع، وقيل من شغر البلد إذا خلا لخلوه من الصداق.`,
      o: NO_O,
      s: `فيكون تفسير الشغار ليس من كلام ابن عمر، فضلًا عن أن يكون من كلام النبي ﷺ، بل هو من تفسير نافع. وسمي نكاح الشغار لأنه خلا عن ذكر الصداق، فصداق كل واحدة بُضع الأخرى، فجُعل فرج هذه في مقابلة فرج هذه.` },
    { q: `هل النهي عن الشغار يقتضي بطلان النكاح؟`, p: `67–68، 70، 72`,
      n: `أجمع العلماء على أنه منهي عنه، واختلفوا: هل هو نهي يقتضي إبطال النكاح أم لا؟ فعند الشافعي يقتضي إبطاله، وحكاه الخطابي عن أحمد وإسحاق وأبي عبيد. وقال مالك: يفسخ قبل الدخول وبعده، وفي رواية عنه: قبله لا بعده. وقال جماعة: يصح بمهر المثل.`,
      o: `القائلون بالصحة بمهر المثل: أبو حنيفة، وحُكي عن عطاء والزهري والليث، وهو رواية عن أحمد وإسحاق، وبه قال أبو ثور وابن جرير.`,
      s: `الراجح أن النكاح يقع باطلًا، وهو قول الجمهور وظاهر قوله ﷺ (لا شغار في الإسلام)؛ فالنفي يتجه إلى أقرب ما يحتمله وهو نفي الصحة، إذ الوجود الحسي واقع، أو يقال: لا وجود شرعي لهذا العقد، وهو المعنى نفسه (نفي الحقيقة الشرعية يساوي نفي الصحة). ووجه البطلان: أن كل عقد من العقدين مشترط فيه العقد الآخر، فيكون من جنس البيعتين في بيعة، ويكون في أركان العقد فساد؛ لأن اشتراط عقد في عقد نهى عنه الشرع، وهو يجعل المعقود عليه - وهو ركن العقد - باطلًا، فالنهي لوصف لازم لا ينفك عن العقد بل لأمر في ذاته؛ إذ العقد يستلزم معقودًا عليه، وهنا المعقود عليه فرج هذه في مقابل فرج هذه، وكل من العقدين يبطل الآخر. أما من قال إن النهي لأجل فساد الصداق فقط، فجعله نهيًا لوصف خارج، فإذا وقع صححه مع الإثم وألزم بمهر المثل، فالصحيح الأول. واختلاف الرواية عن أحمد وإسحاق راجع إلى هذا: هل النهي لوصف لازم أو خارج؛ ولأن أحمد في رواية يقول إن كل نهي يقتضي الفساد ولا يفرق بين ما فيه انفكاك الجهة وما ليس فيه. وقول مالك (يفسخ قبل الدخول وبعده) دليل على بطلانه عنده، أما روايته (قبله لا بعده) فأصل عنده في كثير من العقود من باب المصلحة، والصحيح أنه طالما لم يصح العقد لم يحل الفرج، فلو كان صحيحًا لصح قبل الدخول، والمفاسد تندفع بإعطاء كل ذي حق حقه لا بتصحيح الباطل.` },
    { q: `قاعدة: متى يقتضي النهي بطلان العقد؟ (النهي لذاته، لوصف لازم، لوصف خارج)`, p: `68–70`,
      n: NO_N,
      o: `الحنفية يفرقون بين الباطل والفاسد.`,
      s: `النهي يستفاد منه حكمان: تكليفي (التحريم)، ووضعي (أن الشرع جعله علامة على بطلان العقد). والبطلان معناه أن العقد مفسوخ ابتداءً، فلا يفيد حِلّ الفرج ولا تجوز استدامته، وإن كان قبل الدخول فلا مسمى ولا مهر مثل وإنما يُبيَّن بطلانه. والباطل والفاسد واحد عند الجمهور، والتفريق للحنفية ولا دليل عليه. ويقتضي النهي البطلان إذا كان عن الشيء لذاته أو لوصف لازم له؛ أما إذا كان لوصف خارج غير لازم يمكن تصور الانفكاك عنه (انفكاك الجهة) فيقتضي التحريم دون البطلان. أمثلة المنهي عنه لذاته (فهو محرم باطل): بيع الخمر، والغصب (فما غُصب لا يصير حقًا للغاصب)، والربا (فلا ينتقل الملك في الزيادة إلى الآكل)، ونكاح المحارم، ومهر البغي وحلوان الكاهن. ومثال الوصف الخارج: بيع العنب لمن يتخذه خمرًا، فالعقد محرم لكنه صحيح: ينتقل المال للبائع والعنب للمشتري، ويؤمران بالتوبة، وكذا بيع الحرير لمن يلبسه.` },
    { q: `المال المأخوذ في عقد باطل (مهر البغي، ثمن المخدرات، أجرة المحرم): هل يُرد؟`, p: `69–70`,
      n: NO_N,
      o: `شيخ الإسلام ابن تيمية: هذا المال لا يُرد إلى الزاني حتى لا يُجمع له بين العوض والمعوض، بل يُنفق صدقة. وقال: العقود المحرمة كلها ولو باطلة لا يُرد فيها المال.`,
      s: `الصحيح عند أكثر أهل العلم أنه طالما لم ينتقل الملك لبطلان العقد فالمال ما زال على ملك صاحبه، ولابد أن يُرد إليه إن عُلم، فإن عُجز عن معرفته تصدق به في مصالح المسلمين؛ ويفترق هذا عما إذا كان العقد محرمًا وصحيحًا. والمخدرات والسجائر لا قيمة لها شرعًا فلا يصح العقد عليها، فلو اشترى مخدرات ثم تنازعوا لم يُلزم بدفع ثمنها، ولو أحرقها أو أتلفها فلا قيمة لها. أما إذا كان النهي لوصف خارج، كامرأة تزيّن امرأة تعلم أنها تتبرج، فالتزيين في أصله مباح إذا كان لزوجها، فالمال لها حلال مع الإثم؛ أما الرجل الذي يزيّن المرأة فالفعل نفسه محرم (ينظر إلى شعرها ويمسه)، فلا يحل له المال.` },
    { q: `أحكام نكاح الشغار إذا فُسخ بعد الدخول، وعدة النكاح الباطل ووطء الشبهة`, p: `70–71`,
      n: NO_N,
      o: `العدة من النكاح الباطل ووطء الشبهة عند الجمهور ثلاث حيضات كالنكاح الصحيح.`,
      s: `إذا فُسخ بعد الدخول يجب فيه الصداق بما استحل من فرجها، ويثبت به النسب، ويُدرأ به الحد، كالنكاح بلا ولي فإنه باطل بنص الحديث (أيما امرأة نكحت بغير إذن وليها فنكاحها باطل... فإن دخل بها فلها المهر بما استحل من فرجها) فأثبت لها المهر المسمى، وقوله (بما استحل) دل على أنه رآه حلالًا ولم يأته حرامًا، وليس كمهر البغي؛ ومن هنا كان إثبات النسب في النكاح الذي فيه شبهة. والعدة: الراجح من جهة الدليل قول شيخ الإسلام أنها حيضة واحدة، لأنها لاستبراء الرحم. فإذا انتهت العدة جاز أن يعقد عليها عقدًا صحيحًا مستقلًا بمهر جديد، ولا دليل على تحريمها عليه؛ فالمحرمات منصوص عليهن، وليس منهن من عُقد عليها عقد باطل أو بغير إذن وليها. بل من زنى بامرأة ثم انتهت عدتها من وطئه المحرم فلا مانع من أن يتزوجها إذا تابا إلى الله. ومن يقول إن الزاني لا ينكح إلا زانية (أي العقد) يقول: إذا ظلت على معصيتها فهناك وصف يمنع العقد وهو وصف الزنى، فإذا تابت زال الوصف المحرم فجاز لهما أن يتزوجا، ولكن لابد من انتهاء العدة من الوطء المحرم أو الوطء بشبهة.` },
    { q: `هل يُحسب الفسخ (كفسخ الشغار أو الردة) من الطلقات؟ وهل الخلع طلاق؟ (فتوى)`, p: `71–72`,
      n: NO_N,
      o: `من يجعل الخلع فسخًا لا يحسبه من الطلقات.`,
      s: `الفسخ لعقد باطل لا يُعد من الطلقات الثلاث، فإذا تزوجها بعد ذلك بعقد صحيح لم يُحسب الفسخ الأول طلقة. ومثاله: زوجان سبّ أحدهما الدين فانفسخ النكاح، ثم عاد إلى الإسلام في فترة العدة فعاد النكاح دون تجديد؛ فلا يُعد طلاقًا لأنه فسخ. أما الخلع فالصحيح أنه طلاق يُحسب من الطلقات؛ لأن الرسول ﷺ قال (اقبل الحديقة وطلقها تطليقة) [البخاري]، فسماه طلاقًا وهو المبلغ عن الله، ولأنه وقع في عقد صحيح ثابت وتم بطلب المرأة، وثبتت فيه أحكام الطلاق.` },
    { q: `إذا سُمّي في الشغار صداق، أو عُقد العقدان منفصلين مع التواطؤ على الاشتراط`, p: `72–74`,
      n: `وصورته الواضحة: زوجتك بنتي على أن تزوجني بنتك وبُضع كل واحدة صداق للأخرى، فيقول: قبلت. وأجمعوا على أن غير البنات (الأخوات، بنات الأخ، العمات، بنات الأعمام، الإماء) كالبنات في هذا.`,
      o: `الشافعية: لا بد أن تكون هذه هي الصيغة. أبو حنيفة والشافعي يصححون العقد طالما لم يكن فيه الاشتراط لفظًا، لأن العبرة عندهم بالمباني والصيغة لا بالمقاصد.`,
      s: `الراجح أنه باطل ولا يُصحح بمهر المثل، وهو اختيار الشيخ ابن باز (وله رسالة قيمة في هذا)، بل الشيخ ابن باز يجعل قيد (ليس بينهما صداق) في تفسير نافع غير لازم؛ فالصحيح أنه إذا اشترط في العقد زواج الأخرى ولو بصداق فهو شغار؛ لأن التراضي غير حاصل (فكل منهما عقد مستقل، فلماذا أدخل العقدين معًا؟)، كبيعتين في بيعة، والأغلب أن فيه محاباة في المهر للتساهل فيه لأجل إتمام العقد الآخر. والنهي عن الشغار من رفع شأن المرأة في الإسلام، وألا يكون بُضعها في مقابل بُضع امرأة أخرى، وألا ينتفع وليها بمنفعتها التي تملكها هي، فالمهر حق خالص لها، ففي الشغار إهانة عظيمة للمرأة؛ لذلك نهى الشرع عنه وأبطله على الصحيح. وكذا لو عقدوا عقدين منفصلين بصيغتين مستقلتين، وكل منهما بصداق، لكنهم متواطئون على أن هذا شرط في هذا (ولذلك تجد أحدهم إذا طلق امرأته طلق الآخر أخته)، فالعقود مبناها على المقاصد، والتواطؤ والاتفاق السابق يجعل العقد باطلًا ولو كانت صورته وصيغته صحيحة، فهذا نوع من التحايل؛ وهو قول المالكية والحنابلة، فقد قال النبي ﷺ (لا ترتكبوا ما ارتكبت اليهود فتستحلوا محارم الله بأدنى الحيل)، فتغيير الصيغة مع بقاء المقصود لا يُحل العقد ولا يصححه في الصحيح من أقوال العلماء.` },
    { q: `هل العقود مبناها على الألفاظ أم على المقاصد؟ (مع حكم نكاح التحليل بلا شرط، والنكاح بالمعاطاة)`, p: `73–74`,
      n: NO_N,
      o: `الحنفية والشافعية: أصل العقود على المباني دون المقاصد، ولذلك يصححون زواج التحليل إذا لم يُشترط في الصيغة ولو كان هناك تواطؤ. وأحمد ومالك: هو عقد باطل محرم. وتوسع شيخ الإسلام فقال: ينعقد النكاح بما عدّه الناس نكاحًا بأي لغة ولفظ وفعل كان.`,
      s: `الصحيح أن العبرة بالمقاصد، ودليله (إنما الأعمال بالنيات)، إلا أن يشترط الشرع لبعض العقود ألفاظًا فيضاف اللفظ إلى المقصد. فعقد النكاح عقد شكلي لا بد فيه من ألفاظ تدل على النكاح، فلا يصح بلفظ الإجارة ولا البيع (فلا يقول: بعتك ابنتي أو أجرتك ابنتي)، والناس لا يعدون نكاحًا إلا بلفظ النكاح والتزويج (والهبة على خلاف)، فلا يكون كلام شيخ الإسلام توسعًا في الحقيقة. ولا يصح الزواج بالمعاطاة عند عامة أهل العلم [كأن يسلّموها له يوم الزفاف دون صيغة، كما يقع في بعض القبائل والقرى التي لا يهتمون فيها بالتوثيق، فيقيمون الحفل وينصرف الرجل بزوجته دون عقد]؛ لأنه لم يقع في زمن التشريع عقد نكاح إلا بصيغة، ولم يزل المسلمون يشترطون الألفاظ الصريحة. فإن وقع بالمعاطاة كان باطلًا عند الأئمة الأربعة والظاهرية، لكنه نتيجة الجهل يكون وطء شبهة: يُدرأ به الحد، ويثبت به النسب، ويجب به المسمى إن كان قد دخل بها، ويفارقها، ولا بد أن تنتهي العدة قبل أن يعقد عليها عقدًا جديدًا. والنبي ﷺ لم يزوِّج قط بالمعاطاة، وإنما بالألفاظ وبصداق (اذهب فقد زوجتكها بما معك من القرآن)، إلا في أمر واحد: الرجل يعتق أمته ويجعل عتقها صداقها، فيصح ذلك بنيته، وعند بعض أهل العلم يشترط التلفظ.` },
    ]
  },
  {
    title: `باب الوفاء بالشروط في النكاح (ص74–84)`,
    items: [
    { q: `المراد بـ(أحق الشروط أن يوفى به ما استحللتم به الفروج)`, p: `75`,
      n: `قال الشافعي وأكثر العلماء: محمول على شروط لا تنافي مقتضى النكاح بل تكون من مقتضياته ومقاصده، كاشتراط العشرة بالمعروف، والإنفاق عليها وكسوتها وسكناها، وألا يقصّر في شيء من حقوقها، ويقسم لها كغيرها، وأنها لا تخرج من بيته إلا بإذنه، ولا تنشز عليه، ولا تصوم تطوعًا بغير إذنه، ولا تأذن في بيته إلا بإذنه، ولا تتصرف في متاعه إلا برضاه.`,
      o: `أحمد وجماعة: يجب الوفاء بالشرط مطلقًا لعموم الحديث.`,
      s: `يريد النووي أن هذه الشروط - التي هي من مقتضى العقد وتجب دون اشتراط - هي التي يجب الوفاء بها. والتفصيل الذي ذكره فيه قصور في العرض، والصواب التفصيل الآتي.` },
    { q: `تقسيم الشروط في النكاح وحكم كل نوع`, p: `75–79`,
      n: `وأما شرط يخالف مقتضاه، كشرط ألا يقسم لها، ولا يتسرى عليها، ولا ينفق عليها، ولا يسافر بها، ونحو ذلك، فلا يجب الوفاء به، بل يلغو الشرط ويصح النكاح بمهر المثل، لقوله ﷺ (كل شرط ليس في كتاب الله فهو باطل).`,
      o: `أحمد وجماعة: يجب الوفاء بالشرط مطلقًا.`,
      s: `الشروط ثلاثة أنواع: (1) ما هو من مقتضيات العقد (يجب ولو لم يُشترط). (2) ما ينافي مقتضى العقد: وهو باطل لا يجب الوفاء به باتفاق، كألا يقسم لها بمعنى أن له ألا يأتيها أبدًا، وألا ينفق عليها ولا يسكنها ولا يعاشرها، أو أن يكون زوجها على الورق فقط، أو ألا يتوارثا (كما يفعل بعض الناس خوفًا من ذهاب مال الأب للزوجة الجديدة)، أو أن تخرج متى شاءت ولا تسكن في بيته؛ لأن الزواج يُقصد منه السكن والمودة والرحمة التي تحصل بالسكن والمعاشرة، والرابطة الزوجية لها أحكام تترتب عليها حتى بعد الموت. (3) ما ينافي إطلاق العقد ولا ينافي مقتضاه: كاشتراطها ألا يسافر بها أو لا يخرجها من بلدها أو من مسكن لها فيه مصلحة (كقربه من أولادها)، أو ألا يتزوج عليها أو يتسرى عليها؛ فإطلاق العقد يقتضي أن تسكن حيث سكن (أسكنوهن من حيث سكنتم من وجدكم) وأن له أن يتزوج ويتسرى، فإذا اشترطت خلاف ذلك لمصلحتها فهذا لا ينافي مقتضى العقد لأنها لم تمنعه من الاستمتاع، وهذا هو الذي قال الإمام أحمد وجماعة بوجوب الوفاء به - لا أن مراده وجوب الوفاء بكل شرط ولو نافى مقتضى العقد. والصحيح وجوب الوفاء به؛ لدخوله في عموم (إن أحق الشروط أن يوفى به ما استحللتم به الفروج)، وهو يعارض عموم (كل شرط ليس في كتاب الله فهو باطل)، والترجيح: أن معنى (ليس في كتاب الله) ليس في شرع الله، وهذا الشرط في شرع الله لأن الرسول ﷺ بيّنه، خصوصًا مع حديث فاطمة (فلا آذن ثم لا آذن... إلا أن يريد ابن أبي طالب أن يطلق ابنتي وينكح ابنتهم، فإنما هي بضعة مني يريبني ما أرابها ويؤذيني ما آذاها) [البخاري]؛ فكان شرطًا عرفيًا بين علي والنبي ﷺ ألا يؤذي فاطمة، والشرط العرفي كاللفظي، وعليّ لم يتزوج على فاطمة قط حتى ماتت؛ فهذا دليل على ترجيح عموم (أحق الشروط) على عموم (كل شرط ليس في كتاب الله). وعلى القولين لا يلزم بطلان العقد، لأن الشرط وصف خارج لم يرد نهي صريح عنه، وأقصى ما فيه بطلان الشرط؛ فالفريقان يصححان العقد.` },
    { q: `اشتراط ترك المبيت أو النفقة أو السكنى (زواج المسيار)، وتنازل المرأة عن حقها في القسم`, p: `76–77`,
      n: NO_N,
      o: NO_O,
      s: `اشتراط ألا يقسم لها ولا يبيت عندها ليلًا وإنما يأتيها نهارًا، أو ألا ينفق عليها ولا يسكنها (وهو ما يسمونه زواج المسيار، ويكثر في الزواج الثاني خصوصًا إذا تزوج دون علم الأولى) شرط لا يجوز اشتراطه لأنه ينافي مقتضى العقد، فالعقد مبني على السكن ولزوم البيت والمعاشرة، وهي المقاصد الأصلية منه؛ وهذا لا يجوز عند من يقول بوجوب الوفاء بالشروط وعند من لا يقول به. فإذا تنازلت هي من نفسها وأسقطت حقها فلها ذلك، ولها أن ترجع متى شاءت، وعليه أن يعطيها كافة حقوقها ولا يحتج عليها بالاتفاق. ومثاله في الربا: من اشترط أن يسدد العشرة اثني عشر فشرط ربوي محرم، أما لو أعطى الزيادة عند الأداء دون شرط فلا بأس (فإن خياركم أحسنكم قضاء). وأما هبة سودة يومها لعائشة فجائز، ولها أن ترجع فيما هو آتٍ فتطالب بالقسم، وليس ذلك كالعائد في هبته كالكلب يعود في قيئه؛ إنما العود المذموم أن ترجع فيما مضى، كأن تهب يومها مدة سنة ثم تقول: أردتها لي لا لها.` },
    { q: `اشتراط خروج الزوجة للعمل، وعملها داخل البيت`, p: `78`,
      n: NO_N,
      o: NO_O,
      s: `المتفق على عدم جوازه اشتراط ما ينافي مقتضى العقد، كألا ينفق عليها ولا يسكنها، أو ألا يلزمها استئذانه في الخروج، أو ألا تبقى في بيته، أو ألا تمكنه من نفسها، أو أن تخرج متى شاءت؛ فقد تكون له حاجة إليها وقد خرجت، ومثله أن يدعوها إلى فراشه فتمتنع، والأشد أن تخرج دون استئذان. ومن ذلك ما يشترطه كثير من الناس على الزوج من أنها ستخرج للعمل وليس له منعها، ولو كتبوه في العقد، فهو شرط منافٍ لمقتضى العقد، لأن مقتضاه أن تسكن في بيته وتلازمه، وليس هذا مما يقول الإمام أحمد بوجوب الوفاء به. أما عملها في بيتها (كالخياطة، أو الغزل، أو تجهيز الأطعمة وبيعها) فليس له أن يمنعها منه طالما أنه كلما أراد معاشرتها عاشرها وقد لزمت البيت.` },
    { q: `اشتراط سوء العشرة، واشتراط عدم الإنجاب`, p: `78–79`,
      n: NO_N,
      o: NO_O,
      s: `اشتراط عدم العشرة بالمعروف - كأن يقول لأهلها بعد الطلاق والمشاكل إن أرادت الرجوع فليس لها إلا الضرب والشتم، فيشترط أن يضربها ويهينها ويسبها بغير سبب، أو يشترط التقصير في حقوقها من سكنى وإنفاق وكسوة - شرط منافٍ لمقتضى العقد، لأن العقد مبني على العشرة بالمعروف من جهته، وعلى تسليم نفسها والبقاء في بيته من جهتها. وكذلك اشتراط عدم إنجاب الأولاد شرط باطل محرم ولو لمدة محددة، فالولد حق للطرفين، واشتراط العزل منه أو منها شرط مكروه منافٍ لمقتضى العقد (كأن تقول: عندي أولاد ولا أريد المزيد، أو يقول: أولادي كبار ولو أنجبتِ فسأطلقك)؛ قال تعالى (والله جعل لكم من أنفسكم أزواجًا وجعل لكم من أزواجكم بنين وحفدة)، وقال ﷺ (تناكحوا تكثروا فإني أباهي بكم الأمم يوم القيامة)، فالتناسل من مقاصد العقد. أما إن رغبا في العزل دون اشتراط فهو في حكم العزل الذي سيأتي: مكروه وليس بمحرم، وقد يكون جائزًا إذا كان هناك ضرر على المرأة كالمرض.` },
    { q: `اشتراط خدمة أهل الزوج، وحكم خدمة المرأة زوجها`, p: `79`,
      n: NO_N,
      o: `الجمهور: لا يلزمها خدمة زوجها، بل يأتيها بخادمة.`,
      s: `شرط خدمة غير الزوج (كأبيه وأمه أو أولاده من غيرها) شرط غير واجب عليها، فإن خدمتهم فهو تطوع محض لا يختلف فيه العلماء، ومتى شاءت توقفت؛ وإلزامها بما ليس بلازم لا يجعله واجبًا، كمن اتفق مع زوجته على صلاة ثماني ركعات نفلًا كل يوم فلا يصير النفل فرضًا بذلك. وقول الجمهور بعدم لزوم خدمة زوجها قول مرجوح، والصحيح وجوب خدمة المرأة زوجها وأولادها، وهذا من المعروف.` },
    { q: `اشتراط الزوجة إكمال التعليم (فتوى)`, p: `79`,
      n: NO_N,
      o: NO_O,
      s: `إن كان التعليم وهي في البيت فلا حرج، أما أن تخرج بغير إذنه فلا؛ فلو شرط لهم ذلك ثم خالف لم يكن عليه حرج، لأن خروج المرأة بغير إذن زوجها شرط منافٍ لمقتضى العقد.` },
    { q: `اشتراط الزوجة عدم التعدد عند العقد (فتوى)`, p: `64، 79`,
      n: NO_N,
      o: `اختلف العلماء في وجوب الوفاء به.`,
      s: `لا ينافي مقتضى العقد ولكن ينافي إطلاقه، والصحيح مذهب الإمام أحمد أن اشتراط ما فيه مصلحة للمرأة أو لأحد الطرفين من الشروط التي يجب الوفاء بها، ويؤيده حديث فاطمة لما أراد علي أن يتزوج عليها بنت أبي جهل. وهذا الشرط لا يحرّم عليه الحلال، بل يبيح لها حق الفسخ إن لم يف به. وليس هذا تعطيلًا لحكم شرعي؛ لأنه ليس أمرًا عامًا بل شرط امرأة بعينها، أما التعطيل فأن يُجعل شرطًا عامًا لكل أحد، كالذي نصوا عليه (في القوانين) من اعتبار اقتران زوجها بأخرى إضرارًا بها، فهذا كلام باطل بلا شك، إذ ليس ذلك ضررًا معتبرًا، وفيه إبطال للحكم الشرعي.` },
    { q: `اشترطت الزوجة أن تعيش في بلدها، ثم رأى الزوج المصلحة في نقلها إلى بلده (فتوى)`, p: `79`,
      n: NO_N,
      o: NO_O,
      s: `يجب أن يفي لها بشرطها؛ لأن لها مصلحة في ذلك.` },
    { q: `القسم بين الزوجات: هل عماده الليل أم النهار؟ (فتوى)`, p: `79`,
      n: NO_N,
      o: NO_O,
      s: `القسم لا يصح إلا بالليل بمقتضى العرف الشرعي، وهذا باتفاق أهل العلم؛ فعماده المبيت عندها ليلًا، لأن الليل هو مقتضى السكن، وهو العرف الشرعي الذي كان على عهد النبي ﷺ وأجمع عليه العلماء، ويؤخذ من القرآن: (ومن آياته أن خلق لكم من أنفسكم أزواجًا لتسكنوا إليها)، (هو الذي جعل لكم الليل لتسكنوا فيه)، (وجعل الليل سكنًا). والنهار تابع لليل: فمن المغرب لامرأة ونهار اليوم التالي لها حتى المغرب ثم يذهب إلى الأخرى، وليس أن يجعل النهار لواحدة والليل لأخرى.` },
    { q: `من تزوج امرأة وجعل صداقها طلاق ضرتها (فتوى)`, p: `80`,
      n: NO_N,
      o: NO_O,
      s: `هذا الصداق باطل وعمل محرم، والظاهر - والله أعلم - أنه لو اشترط ذلك واتفقا عليه تواطؤًا أو لفظًا أن العقد يبطل، لأن أحد أركانه (المقابل) مقابل محرم باطل منهي عنه.` },
    { q: `الأجرة على الأعمال المختلف في حلها (كالتصوير الفوتوغرافي)، وعمل (الكوافير الإسلامي) (فتوى)`, p: `80`,
      n: NO_N,
      o: NO_O,
      s: `الأجرة تابعة لحكم العمل: ففي الحال التي يجوز فيها التصوير (على قول من يجيزه) تكون الأجرة حلالًا، وفي الحال التي يحرم فيها تكون الأجرة محرمة. و(الكوافير الإسلامي) للمحجبات والمنتقبات دون ارتكاب المنكرات: فمن المنكرات نمص الحواجب، فهو عمل محرم وأخذ الأجر عليه محرم، ومنها كشف العورة لإزالة الشعر فهو عمل محرم، وفي استحقاق الأجرة عليه نظر لأنه ليس المقصود منه كشف العورة، والأقرب أنه يكون كالرجل الذي يعمل كوافيرًا، فهي منفعة محرمة.` },
    { q: `حكم من عقد على محرم من محارمه: حرام أم كفر وردة؟ (فتوى)`, p: `80`,
      n: NO_N,
      o: `بعض العلماء يجعله محرمًا يجب فيه القتل (حدًا).`,
      s: `لا نزاع في التحريم (حرمت عليكم أمهاتكم...)، والمشكلة في العقد، فالعقد يراد به الاستحلال (واستحللتم فروجهن بكلمة الله)، فعقده على محرمه استحلال لفرجها؛ فإذا سماه زواجًا ونكاحًا ولم يسمه زنى أو سفاحًا فالصحيح أنه ردة عن الإسلام. ومثله المسلمة تتزوج نصرانيًا أو يهوديًا وهي تعلم التحريم، فتذهب إلى الكنيسة أو المعبد وتقيم مراسم الزواج وتسميه زواجًا، فهذا استحلال لما حرم الله. ويبقى النظر في الجهل: فقد لا يعلم الشخص أن هذه المرأة من محارمه، كمن يجهل تحريم الجمع بين المرأة وعمتها أو خالتها، أو بين امرأة وبنت أختها أو بنت أخيها، فهذا يُنظر فيه بالجهل.` },
    { q: `وقوع الطلاق في الحيض والنفاس (الطلاق البدعي) (فتوى)`, p: `80–84`,
      n: NO_N,
      o: `شيخ الإسلام ابن تيمية وابن القيم: لا يقع الطلاق البدعي، واعتمدا على رواية أبي الزبير عند أبي داود (فردها علي ولم يرها شيئًا)، وحمل ابن القيم ما عداها على أنه اختلط على الرواة.`,
      s: `سُئل عن رجل طلق امرأته مرة في طهر ومرة في حيض ومرة في نفاس، فأفتاه شيخ بكفارة يمين بإطعام ستين مسكينًا: فقال: هذا كلام لا قائل به بالمرة، ولا حتى شيخ الإسلام الذي لا يوقع الطلاق في الحيض قال بكفارة اليمين؛ فكفارة اليمين ليس فيها ستون مسكينًا، وليس هذا ظهارًا. أما القول بعدم وقوع الطلاق البدعي فقول قد نعذر قائله، لكننا نفتي ببطلانه لأنه خلاف النص الصريح: حديث ابن عمر (مره فليراجعها)، والمراجعة تحمل على المعنى الشرعي لا اللغوي، وقد ثبت أن النبي ﷺ قال (هي واحدة) - صححه ابن حجر والألباني وابن السكن - فلا عبرة بقول أحد مع قول رسول الله ﷺ. وقول ابن تيمية وابن القيم (وهما على العين والرأس) مخالف لنص الحديث. ورواية أبي الزبير (ولم يرها شيئًا) أنكرها أبو داود والخطابي، ولو صحت فالضمير عائد على الحيضة التي وقعت فيها الطلقة، أي لا تُحسب من العدة، لا أن الطلقة لا تُحسب؛ وابن عمر صاحب القصة وأدرى الناس بها، وقد أفتى بأصح الأسانيد بوقوع الطلاق في الحيض. فالرجل المذكور قد بانت منه زوجته. والقول بعدم الوقوع ليس مرجوحًا فقط بل باطل؛ إذ لو كان مرجوحًا لكانت المسألة اجتهادية، والنص موجود، والأئمة الأربعة على خلافه، وابن عبد البر يقول: لا يقول بعدم وقوعه إلا أهل البدع، وشيخ الإسلام - رغم جلالته - ليس له سلف في هذه المسألة. أما القانون المصري فيوقع الطلاق في الحيض، ولجنة الفتوى الملتزمة بالمذهب الحنفي تعمل بالتلفيق: توقع الطلقة الأولى والثانية ولا توقع الثالثة! وهذا ليس قول أحد من أهل العلم نهائيًا - ولا حتى شيخ الإسلام وابن القيم - وهو معاملة لأقوال الفقهاء كأنها أدلة شرعية بلا ترجيح، طلبًا للتيسير على الناس في ظنهم، ولو علم الناس أن الطلاق يقع لانتهوا عنه وعلموا خطر هذه الكلمة.` },
    { q: `الطلاق المعلق (إن فعلتِ كذا فأنتِ طالق) (فتوى)`, p: `83`,
      n: NO_N,
      o: NO_O,
      s: `الراجح أن عليه كفارة يمين إذا كان غرضه الحث أو المنع، لأنه بمنزلة النذر (نذر اللجاج)، وهي فتوى الصحابة: فقد حلفت ليلى بنت العجماء أن كل مملوك لها حر، وكل مال لها هدي، وهي يهودية ونصرانية إن لم تفرق بين مولاها وامرأته، فأفتاها عائشة وابن عمر وابن عباس وحفصة وأم سلمة أن تكفّر عن يمينها وتخلي بينهما [الدارقطني]؛ فهذا عتق صريح لكنه معلق لا ناجز، فجعلوه بمنزلة (عليّ أن أعتق عبيدي). فالذي يقول (أنت طالق لو فعلت كذا) بمنزلة (عليّ أن أطلقك)، فكأنه قال (والله لأطلقنك إن فعلت)، فيؤمر بكفارة يمين وهو لا يقصد الطلاق في الحقيقة. أما إن قال (أنت طالق) باللفظ الصريح المنجز، فيُنظر: هل كان مجنونًا ساعتها أو غضبان قد زال عقله بالكلية؟ فهذا الذي يُبحث في سقوط التكليف عنه حينها، أما أن الطلاق لا يقع لأنه وقع في الحيض فهذا كلام باطل. وقول شيخ الإسلام في مسألة (لو فعلت فأنت طالق) قوي لورود أقوال الصحابة فيها.` },
    ]
  },
  ]
};
